      "content": "中国青年网呼和浩特10月25日电（记者 安俐）10月20日，由中央网信办网络传播局指导，内蒙古自治区党委网信办、内蒙古自治区教育厅、共青团内蒙古自治区委员会、内蒙古大学、中国青年网共同主办的“青春华章・逐梦北疆”网络主题宣传活动（青春分享会）上，世纪互联乌兰察布基地资源开发部总监周以光以《世界算力浪潮奔涌，内蒙古何以崛起？青年机遇何在？》为题，分享了乌兰察布从草原城市走向算力产业发展高地的变化，也向青年学子展示了家乡正在孕育的新机遇。周以光进行分享。中国青年网记者 安俐 摄2022年，周以光随集团领导来到乌兰察布，为算力中心项目寻找建设地点。彼时的大数据产业园片区还比较荒凉，大风经常会刮起沙尘暴。几年后，随着一座座算力中心拔地而起，曾经看似平常的自然条件，成为当地发展数字经济的独特优势。乌兰察布风能、太阳能资源丰富，能够为算力中心提供源源不断的绿色电力；毗邻北京，光缆往返时延短；年均气温4…"
