      "content": "10月24日，中国体育代表团在闭幕式前入场。当地时间10月24日，第五届亚洲残疾人运动会闭幕式在日本名古屋举行。邓智炜/摄（新华社发）本报讯（中青报・中青网记者 梁璇）第五届亚残运会于当地时间10月24日晚在日本名古屋落幕。中国体育代表团共获得207枚金牌、117枚银牌、111枚铜牌，奖牌总数达435枚，位居金牌榜和奖牌榜首位，连续五届位居亚残运会金牌榜、奖牌榜首位，创造境外参赛最好成绩。本届赛事，中国残疾人运动员共刷新11项世界纪录、18项亚洲纪录。中国残联副理事长、中国体育代表团副团长兼秘书长常征介绍，这是我国境外参赛规模最大、运动员人数最多的一届亚残运会。代表团共派出312名运动员，参加17个大项、335个小项的角逐。传统优势项目表现突出。游泳队收获64枚金牌，田径队获得54枚金牌，4名田径运动员创造4项世界纪录。轮椅网球队在女子单打、双打项目中先后战胜世界排名第一的日本选手，夺得金…"
