      "content": "同心协力，奔赴充满光荣和梦想的远征——习近平总书记在纪念中国工农红军长征胜利90周年大会上的重要讲话鼓舞广大干部群众接续奋斗开创未来来源：新华网作者：新华社记者2026-10-24 09:11:53新华社北京10月23日电题：同心协力，奔赴充满光荣和梦想的远征——习近平总书记在纪念中国工农红军长征胜利90周年大会上的重要讲话鼓舞广大干部群众接续奋斗开创未来新华社记者“长征的历史从未远去，长征的路在不断延伸。”“新征程是充满光荣和梦想的远征，是党和人民的新长征。”习近平总书记10月22日在纪念中国工农红军长征胜利90周年大会上发表重要讲话，在广大干部群众中持续引发强烈共鸣。大家表示，要更加紧密地团结在以习近平同志为核心的党中央周围，坚持以习近平新时代中国特色社会主义思想为指导，深刻领悟“两个确立”的决定性意义，增强“四个意识”、坚定“四个自信”、做到“两个维护”，大力弘扬伟大长征精神，接续奋…"
