      "content": "坚持党的领导，凝心聚力奋进新征程——论学习贯彻习近平总书记在纪念中国工农红军长征胜利90周年大会上重要讲话来源：经济日报作者：评论员2026-10-24 09:12:27在纪念中国工农红军长征胜利90周年大会上，习近平总书记深情回望气壮山河的长征史诗，深刻阐释历久弥新的长征精神，系统指明了新时代传承红色血脉、接续奋斗前行的实践路径。从革命年代浴血突围，到建设时期自力更生，再到新时代伟大变革，坚持党的全面领导始终是贯穿其中的一条主线。历史已充分证明，长征能够突破困局、走向胜利，最核心的优势、最根本的保障就是党的集中统一领导。正是在党的正确领导下，疲惫困顿的队伍才有了坚定信仰，杂乱无序的行动才有了战略方向，一度濒临绝境的革命事业才向着光明、不断走向胜利。同心协力、团结奋斗，是长征精神的鲜明底色，也是新时代攻坚克难的力量源泉。长征从来不是孤军奋战的跋涉，而是党引领人民、军民同心、众志成城的伟大征…"
