      "content": "发挥文物在构建文化遗产大保护格局中的突出作用来源：人民日报作者：陆琼2026-10-24 09:13:22《文化遗产保护传承“十五五”规划》注重全局思维，为文物保护、考古研究和博物馆建设提供系统性发展的“路线图”“任务书”。赋能、明责、共赢，突出强强联合、协同发力，整合各方资源优势，推进系统性保护，文物保护正在构建从单方主责主体走向部门协同、各尽其职、多元共创的开放生态。《文化遗产保护传承“十五五”规划》聚焦未来五年文化遗产保护传承工作中心任务，注重全局思维，统筹谋划各项举措和工程项目，为文物保护、考古研究和博物馆建设提供系统性发展的“路线图”“任务书”，突出构建文化遗产工作的协作机制与作用彰显。规划加强不可移动文物保护与考古工作。针对不可移动文物，规划要求提升保护水平，加强保护管理、落实保护前置、强化分类保护；加大各级文物保护单位公布力度、健全低级别不可移动文物监管体系；加强文物保护修缮…"
