      "content": "央视网消息（新闻联播）：西藏那曲市巴青县7.0级地震抢险救灾加紧进行，人员搜救、伤员救治、群众安置等各项工作全力展开。地震发生以来，各路救援力量在震区持续开展人员搜救，目前已进行了3轮挨家挨户全覆盖排查。76名受伤群众已全部得到及时救治，一些伤情较重人员已转运到市、自治区的相关医院开展进一步治疗。受灾群众安置工作抓紧进行。10月24日凌晨，500套安置板房已经全部运抵巴青县玛如乡。截至24日11时，52450件套各级救灾物资已运抵震区，包括活动板房、棉衣、折叠床等。震区基础设施抢修加紧展开。目前，巴青县道路交通主干道已畅通，已有2201户受影响用户恢复供电。按照应急管理部部署，2支国家安全生产应急救援队伍目前正在受灾地区开展灾情监测，动态研判次生灾害风险，保障救援现场安全。中央气象台预报显示，未来三天，巴青县最低气温将在零下5摄氏度左右，气温低，体感寒冷，当地全力做好抗震救灾和安置人员的防…"
