      "content": "10月22日22时33分许，西藏那曲市巴青县发生7.0级地震。截至10月23日13时，已造成16人遇难、76人受伤，房屋倒塌及受损339户。目前，地震抢险救援工作正在抓紧进行。仍在黄金救援期多方力量有序开展各项抢险工作此次地震震级高、震源浅，震中核心区域部分房屋倒塌、电力通信设施受损。地震进入黄金救援期，多方力量有序开展搜救安置等各项抢险工作。西藏共投入各类救援力量5000余人，救援人员逐户逐点开展摸排搜救。记者23日18时从西藏那曲市巴青县7.0级地震前线应急指挥部获悉，经过3轮挨家挨户全覆盖排查，到目前未发现失联人员。西部战区启动应急响应 部队驰援巴青震区地震发生后，西部战区联指中心迅速启动应急响应机制，统一调动部队各支力量赶赴受灾村镇，开展搜救和转移安置工作。抵达灾区后，救援力量第一时间展开抢险安置工作。现场分工编组、协同作业，抢抓时间搭建临时安置帐篷，引导受灾群众有序撤离危险区域，…"
