      "content": "习近平对西藏那曲市巴青县7.0级地震作出重要指示来源：新华网2026-10-23 10:17:14习近平对西藏那曲市巴青县7.0级地震作出重要指示强调全力开展人员搜救　妥善安置受灾群众切实保障人民群众生命财产安全李强作出批示新华社北京10月23日电　10月22日22时33分许，西藏那曲市巴青县发生7.0级地震，造成重大人员伤亡。地震发生后，中共中央总书记、国家主席、中央军委主席习近平高度重视并作出重要指示指出，西藏那曲市巴青县发生7.0级地震，造成重大人员伤亡。要全力开展人员搜救，全力做好伤员救治工作，最大限度减少人员伤亡。习近平强调，灾区地处高海拔地区，天气寒冷，要密切监测震情和天气变化，科学实施救援，防止发生次生灾害。要抓紧调拨抢险救援物资，妥善安置受灾群众，抢修受损基础设施，切实保障人民群众生命财产安全。中共中央政治局常委、国务院总理李强作出批示指出，要抓紧核实灾情，全力组织抢险救援…"
