      "content": "求是网评论员：同心协力走好新的长征路来源：求是网作者：求是网评论员2026-10-23 23:44:56“红军不怕远征难，万水千山只等闲。”90年前，以红一、红二、红四方面军在会宁和将台堡会师为标志，中国工农红军长征胜利结束。习近平总书记在纪念中国工农红军长征胜利90周年大会上发表重要讲话，回顾我们党领导红军进行长征的伟大历程，总结长征胜利的伟大意义，揭示长征胜利蕴含的党和人民军队铿锵前进的制胜之道，激励全党全军全国各族人民大力弘扬伟大长征精神、同心协力走好新的长征路。90年前的红军长征，历时之长、规模之大、行程之远、环境之险恶、战斗之惨烈，在中国历史上是绝无仅有的，在世界战争史乃至人类文明史上也是极为罕见的。它是“激动人心的远征史诗”，更是“人类有文字记载以来最令人振奋的大无畏事迹”。长征的胜利，实现了中国共产党和中国革命事业从挫折走向胜利的伟大转折，开启了中国共产党为实现民族独立、人民…"
