      "content": "为改革完善全球治理贡献中国方案赵申洪2026年10月23日08:30来源：光明日报222订阅取消订阅已收藏收藏大字号点击播报本文，约【特别关注】10月23日至25日，2026全球治理论坛（雄安）将在河北雄安新区举办。来自90余个国家的嘉宾将围绕“重建信心与合作：百年变局与改革完善全球治理”主题展开研讨。这是全球治理倡议提出一年多来，中国推动国际社会凝聚共识、探索行动路径的一次重要实践，也是向世界系统阐释中国全球治理主张的重要平台。中国曾被挡在联合国大门之外长达22年，但从未动摇对多边主义的信念。恢复联合国合法席位后，中国逐步成为全球治理的建设者、贡献者。党的十八大以来，中国的角色从参与者走向引领者，在全球治理体系改革进程中发挥着越来越重要的作用。当前，全球治理正处在关键十字路口。联合国成立80余年，会员国从51个增至193个，全球南方的群体性崛起深刻改变了国际力量对比，但全球治理体系的代表…"
