      "content": "在世界历史进程中把握长征的时代价值肖光文 李永超2026年10月23日08:29来源：光明日报222订阅取消订阅已收藏收藏大字号点击播报本文，约今年是中国工农红军长征胜利90周年。90年来，这场发生在中国大地上的伟大远征始终吸引着世界的目光。长征迸发出的激荡人心的强大力量，跨越时空，跨越民族，是人类为追求真理和光明而不懈努力的伟大史诗。在世界历史的坐标中审视长征，能够更加深刻地认识这一伟大壮举的国际意义。长征顺应了世界反法西斯战争的历史大势20世纪30年代，日本帝国主义加紧侵略中国，中华民族面临空前危机。中国共产党在长征中高举抗日救亡旗帜，把解决生存危机同拯救民族危亡联系起来，把长征的大方向同建立抗日前进阵地联系起来。红军沿途宣传抗日救国主张，动员各族群众，推动抗日救亡运动发展。长征的胜利，保存和锻炼了中国革命的骨干力量，实现了北上抗日的战略转移，为开展抗日民族战争创造了有利条件。长征胜利…"
