      "content": "习近平：在纪念中国工农红军长征胜利90周年大会上的讲话来源：新华网2026-10-22 15:13:07新华社北京10月22日电在纪念中国工农红军长征胜利90周年大会上的讲话（2026年10月22日）习近平同志们：今天，我们隆重集会，纪念中国工农红军长征胜利90周年。90多年前，我们的国家和民族内忧外患，日寇加紧对华侵略，国民党反动派向中国共产党领导的革命根据地接连发动大规模“围剿”。由于“左”倾教条主义在党内的错误领导，中央革命根据地第五次反“围剿”失败，其他革命根据地也遭受挫折，党和红军到了生死存亡的危急关头。在这样的严峻形势下，从1934年10月至1936年10月，我们党领导红军第一、第二、第四方面军和第二十五军，进行了震撼世界、彪炳史册的伟大长征。红军长征纵横十余省，长驱二万五千里，跨越近百条江河，翻越皑皑雪山，穿过茫茫草地，进行600余次战役战斗，粉碎上百万敌军围追堵截，宣告国民…"
