      "content": "纪念中国工农红军长征胜利90周年大会在京隆重举行 习近平出席大会并发表重要讲话来源：新华网2026-10-22 10:41:39纪念中国工农红军长征胜利90周年大会22日上午在京隆重举行。中共中央总书记、国家主席、中央军委主席习近平出席大会并发表重要讲话。中共中央政治局常委李强、赵乐际、王沪宁、蔡奇、丁薛祥、李希，国家副主席韩正出席大会。扫描二维码分享到手机网站编辑 - 汤宝兰 张盼 审核 - 张西立【网站声明】纪念中国工农红军长征胜利90周年大会在京隆重举行 习近平出席大会并发表重要讲话"
