      "content": "李强会见俄罗斯总统普京来源：新华网作者：记者 王作葵 刘畅2026-10-22 09:53:0710月21日下午，国务院总理李强在圣彼得堡会见俄罗斯总统普京。新华社记者 黄敬文 摄新华社圣彼得堡10月21日电（记者王作葵 刘畅）10月21日下午，国务院总理李强在圣彼得堡会见俄罗斯总统普京。李强首先转达习近平主席对普京总统的亲切问候和良好祝愿。李强表示，在国际形势持续复杂演变的背景下，中俄保持着紧密协作，是变乱交织的世界中难能可贵的稳定力量。今年以来，两国元首两度会晤，就深化中俄关系与合作作出进一步规划。中方愿同俄方加强战略沟通，夯实政治互信，拓展全方位互利合作，持续增进两国人民福祉。李强指出，中方愿同俄方更好发挥经济互补优势，维护当前双方合作的良好发展态势，加强能源资源、经贸投资、交通运输等务实合作，取得更多积极成果，促进两国共同繁荣。双方要扎实办好“中俄教育年”，不断深化文化、旅游、体育…"
