      "content": "丁薛祥会见2026年国际科学理事会中期会员大会暨北京科学对话部分外宾来源：新华网作者：记者 王慧慧2026-10-22 09:53:0710月21日，中共中央政治局常委、国务院副总理丁薛祥在北京会见2026年国际科学理事会中期会员大会暨北京科学对话部分外宾。新华社记者 刘卫兵 摄新华社北京10月21日电（记者王慧慧）中共中央政治局常委、国务院副总理丁薛祥21日在北京会见2026年国际科学理事会中期会员大会暨北京科学对话部分外宾。丁薛祥表示，科学技术是人类共同的财富，开放合作是科技创新的必然选择。中国愿同各方一道，坚守科学初心，弘扬科学精神，以开放包容畅通国际学术交流，以协同攻关破解前沿科技难题，以互利合作促进成果普惠共享，共同推动全球科技事业发展。国际科学理事会主席格鲁克曼等发言，赞赏中国科技创新取得的成就，表示坚定支持开放合作，让科学真正成为全球公共产品，为全人类共同发展进步贡献更大力量…"
