      "content": "齐心协力走好新的长征路——纪念中国工农红军长征胜利九十周年来源：人民日报2026-10-22 09:08:32岁月砥砺初心，精神照亮征程。90年前，中国共产党领导中国工农红军跨越千山万水，战胜千难万险，胜利完成震撼世界、彪炳史册的伟大远征，实现了中国共产党和中国革命事业从挫折走向胜利的伟大转折。山河巨变、薪火赓续。90年来，长征这座巍峨丰碑愈发光辉闪耀，激励一代代中华儿女攻坚克难、勇毅前行。党的十八大以来，以习近平同志为核心的党中央团结带领亿万人民坚守初心使命，继承和发扬革命传统，大力弘扬伟大长征精神，在新时代的长征路上不断创造新的历史辉煌，实现中华民族伟大复兴势不可挡。“现在，我们正阔步行进在全面建设社会主义现代化国家的新征程上，要齐心协力走好新的长征路”。习近平总书记的话语贯通历史、现在和未来，凝聚磅礴力量、鼓舞强大斗志。开创新时代、开启新征程，这是勇担历史使命的壮阔远征。“今天，我们…"
