      "content": "新兴领域良性循环加快形成来源：人民日报作者：刘志成2026-10-22 10:54:40日前，国家统计局发布了2026年前三季度国民经济运行数据，中国经济交出了一份含金量十足的成绩单，动能向新、结构向优、质效向好的发展态势显著。透过数据，我们看到推动经济平稳运行的积极因素累积增多，新旧动能正在加快转换，民生保障扎实有力，高质量发展的基础更加坚实。三季度经济数据的一个突出亮点，是主要指标增速边际上显著回升。经济增速是市场关注的焦点，也是研判经济运行态势的重要标尺。从总量看，三季度GDP（国内生产总值）同比增长4.5%，高于市场普遍预期的4.4%，也高于二季度的4.3%；环比增长1.2%，既高于二季度的0.9%，也高于上年同期的1.1%。GDP同比和环比增速同步改善，充分反映经济内生动能明显增强，也反映在应对外部冲击方面，宏观政策有力有效。从供给侧看，9月规模以上工业增加值、服务业生产指数同比…"
