      "content": "“党的创新理论专家谈”习近平党建思想——在推进新时代党的建设新的伟大工程中展现出强大实践伟力2026年10月22日09:40来源：人民网-理论频道222订阅取消订阅已收藏收藏大字号点击播报本文，约习近平党建思想围绕“建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党”的重大时代课题，以“十四个坚持”为内涵要义，把党的建设放到党和国家事业发展全局中来认识和谋划，把管党治党、兴党强党同强国建设、民族复兴贯通起来，把党的领导和党的建设统筹起来，在守正与创新的统一中不断把对共产党执政规律和党的自身建设规律的认识提升到新的高度。(责编：黄瑾、秦华)学习路上时习之习近平系列重要讲话数据库中央文件学习宣传贯彻党的二十大精神跟着总书记学党史数据库中央和国家机关建设模范机关言之有理学习文选微信“扫一扫”添加“学习大国”分享到：推荐阅读打开客户端体验更多服务打开"
