      "content": "丁薛祥在河北雄安新区出席国家数据集团有限公司成立大会并调研来源：新华网作者：记者 齐中熙2026-10-21 10:28:3210月20日，国家数据集团有限公司成立大会在河北雄安新区举行。中共中央政治局常委、国务院副总理丁薛祥出席并为公司成立揭牌。这是丁薛祥出席国家数据集团有限公司成立大会并讲话。新华社记者 王晔 摄新华社雄安10月20日电（记者齐中熙）国家数据集团有限公司成立大会20日在河北雄安新区举行。中共中央政治局常委、国务院副总理丁薛祥出席并为公司成立揭牌。丁薛祥表示，组建国家数据集团有限公司，是以习近平同志为核心的党中央从全局和战略高度作出的重要决策部署，对于充分把握人工智能发展先机、加快建设数字中国、构筑国家竞争新优势具有重要意义。要以习近平新时代中国特色社会主义思想为指导，按照党中央和国务院要求，切实做好公司组建运营工作，努力打造世界一流数据科技企业。丁薛祥强调，国家数据集团…"
