      "content": "坚持正确政治方向 夯实共同思想根基——习近平总书记致中央社会主义学院建院70周年的贺信汇聚同心奋进新征程强大力量来源：新华网作者：新华社记者2026-10-21 09:09:34新华社北京10月20日电题：坚持正确政治方向 夯实共同思想根基——习近平总书记致中央社会主义学院建院70周年的贺信汇聚同心奋进新征程强大力量新华社记者在中央社会主义学院（简称中央社院）建院70周年之际，习近平总书记发来贺信表示祝贺。习近平总书记的亲切关怀令统一战线广大成员深受鼓舞。大家表示，要坚决贯彻落实总书记贺信精神，坚持正确政治方向，广泛凝聚政治共识，不断巩固和发展新时代爱国统一战线，更好服务党和国家工作大局，同心奋进新征程。“2016年，习近平总书记对中央社会主义学院建院60周年致信祝贺。时隔10年再致贺信，充分体现总书记对统一战线和多党合作事业的高度重视、对中央社会主义学院的亲切关怀。”在建院70周年庆祝大…"
