      "content": "长征是检验识别领导干部的试金石来源：学习时报作者：陈东恒2026-10-21 10:19:25长征是宣言书、宣传队、播种机，也是党在生死绝境中检验识别领导干部、重塑领导体系的试金石。艰苦卓绝的考验，不仅宣示了革命主张、武装了人民群众、播撒了科学真理，也构建起以“战场识干部、危难辨初心、实绩定任免”为核心逻辑，以实事求是为基石、政治忠诚为根本、斗争实绩为基线、群众立场为底色、动态考察为关键的领导干部考察体系，实现了对政治立场、理想信念、执行能力、宗旨意识、纪律品格的全面考察，锻造出信念坚定、政治忠诚、敢打必胜、求真务实、团结为民、担当作为的骨干力量。检验识别领导干部具有突出的方向性，必须坚持党管干部、组织选人长征检验识别领导干部的历史，是党在极端困难条件下探索科学选人用人机制的生动实践。这场远征不仅是一次伟大的军事战略转移，也是对我军领导干部队伍的筛选。在这场大考中，我们党不仅依靠自我革命完…"
