      "content": "牢固树立和践行人民城市理念来源：经济日报作者：唐 燕2026-10-21 09:09:36当前，我国城镇化正从快速增长期转向稳定发展期，城市建设从大规模增量扩张转向存量提质增效为主的阶段。今年7月，习近平总书记在上海考察时强调，“要全面践行人民城市理念，坚持问需于民、问计于民、问效于民，做深做细做实城市更新各项工作，不断增强居民群众的获得感、幸福感、安全感”。2025年召开的中央城市工作会议从全局和战略高度明确了建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市的目标。“人民城市人民建，人民城市为人民”的重要理念正在深刻重塑我国城市发展的逻辑，为破解公共品供给、发展动力、制度保障等方面的难题提供了指引。优化公共基础设施配置习近平总书记强调，“城市的核心是人，城市工作做得好不好，老百姓满意不满意、生活方便不方便，是重要评判标准”。城市能不能正常运转、群众生活是否方便，很大程度上取决于公共…"
