      "content": "李强会见白俄罗斯总理图尔钦来源：新华网作者：记者 安晓萌 江宥林2026-10-20 08:46:2110月19日下午，国务院总理李强在杜尚别出席上海合作组织成员国政府首脑（总理）理事会第二十五次会议期间会见白俄罗斯总理图尔钦。新华社记者 张领 摄新华社杜尚别10月19日电（记者安晓萌　江宥林）10月19日下午，国务院总理李强在杜尚别出席上海合作组织成员国政府首脑（总理）理事会第二十五次会议期间会见白俄罗斯总理图尔钦。李强表示，中国和白俄罗斯是相互信任支持的真朋友。在习近平主席和卢卡申科总统战略引领下，中白全天候全面战略伙伴关系持续稳健发展，取得丰硕合作成果。明年中白将迎来建交35周年，中方愿同白方一道弘扬传统友谊，巩固战略互信，拓展互利合作，共同促进发展繁荣，不断增进两国人民福祉。李强指出，中方愿同白方加强发展战略对接，进一步发挥两国政府间合作机制作用，充分释放中白服务贸易和投资协定的积…"
