      "content": "求是网评论员：前三季度4.6%的增速说明了什么来源：求是网作者：求是网评论员2026-10-20 19:41:41国家统计局近日公布的数据显示，今年前三季度，我国国内生产总值同比增长4.6%，在全球主要经济体中保持领先；经济增量达5.7万亿元，是近五年同期最大规模增量。总的来看，我国经济顶住压力保持了平稳运行，经济增速符合预期，为实现全年目标奠定了坚实基础。今年以来，外部环境变化对国际大宗商品价格、产业链供应链造成冲击，世界主要经济体普遍遭受不同程度的影响。面对复杂严峻的国内外形势，为什么前三季度我国经济能够实现4.6%的增速，展现出强大抗冲击能力和自我调节能力？背后是新产业不断壮大、新需求拔节生长，是经济动能加快向新、经济结构持续向优。今年1—9月份，我国制造业继续保持合理比重，先进制造业的智能化、绿色化、融合化水平持续提升，新型服务业、研发型服务业实现较快增长，新动能对经济增长的贡献率…"
