      "content": "自然资源部原党组成员，国家林草局原党组书记、局长张建龙严重违纪违法被开除党籍2026年10月20日08:25来源：人民网－人民日报222订阅取消订阅已收藏收藏大字号点击播报本文，约本报北京10月19日电 （记者史一棋）经中共中央批准，中央纪委国家监委对自然资源部原党组成员，国家林业和草原局原党组书记、局长张建龙严重违纪违法问题进行了立案审查调查。经查，张建龙丧失理想信念，背弃初心使命，政绩观错位，对党中央有关要求只表态不落实，对抗组织审查；违反中央八项规定精神，违规收受礼金、接受宴请；不按规定报告个人有关事项，在组织谈话函询时不如实说明问题，在干部选拔任用、职工录用等工作中违规为他人谋取利益；贪欲膨胀，以权谋私，大搞权钱交易，利用职务便利为他人在林地占用和专项资金审批、野生动物利用许可、工程项目承揽等方面谋利，并非法收受巨额财物。张建龙严重违反党的政治纪律、组织纪律、廉洁纪律和生活纪律，构…"
