      "content": "“党的创新理论专家谈”习近平外交思想——新时代我国对外工作的根本遵循和行动指南2026年10月20日09:02来源：人民网-理论频道222订阅取消订阅已收藏收藏大字号点击播报本文，约习近平外交思想是新时代我国对外工作的根本遵循和行动指南。习近平总书记开创性提出的共建“一带一路”倡议，打造了世界上范围最广、规模最大的国际合作平台，为构建人类命运共同体提供了重要实践平台。习近平总书记提出全球发展倡议、全球安全倡议、全球文明倡议、全球治理倡议，为破解全球发展难题、应对国际安全挑战、促进文明互学互鉴、加强完善全球治理贡献中国智慧、中国力量。(责编：黄瑾、秦华)学习路上时习之习近平系列重要讲话数据库中央文件学习宣传贯彻党的二十大精神跟着总书记学党史数据库中央和国家机关建设模范机关言之有理学习文选微信“扫一扫”添加“学习大国”分享到：推荐阅读打开客户端体验更多服务打开"
