      "content": "李强会见塔吉克斯坦总统拉赫蒙来源：新华网作者：记者 安晓萌 刘畅2026-10-19 16:47:39新华社杜尚别10月19日电（记者安晓萌　刘畅）10月19日上午，国务院总理李强在杜尚别会见塔吉克斯坦总统拉赫蒙。李强表示，当前，中塔正推动构建两国命运共同体。今年5月，习近平主席同拉赫蒙总统举行会晤，就双边关系发展进一步作出规划。中方珍视同塔方的深厚友谊，将始终从战略高度和长远角度看待中塔关系，愿同塔方巩固深化政治互信，坚定支持彼此核心利益，不断提升合作质效，在实现现代化的道路上持续携手前行。李强指出，中方愿同塔方扩大双边贸易规模，加强基础设施、绿色矿产、互联互通等领域合作，拓展数字经济、人工智能等新兴产业合作，共同壮大经济增长动能。双方要深化执法安全合作，加强情报交流共享，共同打击“三股势力”，维护地区持久和平稳定。希望塔方继续采取有力措施，保障中方在塔人员和企业的安全。中方全力支持塔方…"
