      "content": "推进有效市场和有为政府相结合来源：光明日报作者：吴毅君 胡琪鹃2026-10-19 14:21:28据报道，近日，市场监管总局批复在长三角开展民用水表、燃气表出厂检定与首次强制检定合并实施互认试点。该试点实现了全国首次在区域范围内的计量器具“一次检定、区域通行”，为计量领域加快建设全国统一大市场、推进长三角区域一体化发展提供了重要的“长三角样板”。以往民用水表、燃气表在某省完成检定，卖到邻省还要重复强制检定，增加企业成本、拉长上市周期。沪苏浙皖范围内，检定资质与检定结果全域互认，不再重复检定，产品交付周期平均缩短一半，降低跨区域流通成本。水表、燃气表生产企业自主开展生产、跨区域销售，根据市场需求拓展长三角各地市场，商品要素天然有跨区域自由流动的诉求；市场竞争倒逼企业降低成本、提升产品质量。这正是有效市场的生动体现。政府不干预企业生产定价，而是破除行政区划带来的制度壁垒，统一计量监管规则，清…"
