      "content": "用好财税杠杆撬动新质生产力来源：经济日报作者：曾金华2026-10-19 14:21:30财税政策在促进新质生产力中意义重大，如何更好发挥政策实效十分关键。在资金投入方面，需强化资金保障和政策供给，放大财政资金乘数效应。在税收引导方面，则需进一步完善机制、优化服务。作为我国激励企业加强科技创新的重要税收工具，研发费用加计扣除政策通过税前额外扣除的制度设计，形成“研发投入越多、减税力度越大”的正向激励机制。统计显示，今年上半年，研发费用加计扣除等支持企业创新投入和技术转让的政策减税降费达6596亿元。科技创新是发展新质生产力的核心要素，研发投入则是科技创新的源头活水。研发费用加计扣除政策在撬动全社会研发投入、支撑高水平科技自立自强中发挥着越来越大的作用，这也是财税政策促进新质生产力发展的体现。近日，中共中央、国务院印发《关于发展新质生产力的意见》（以下简称《意见》），其中强调要统筹好政府和市…"
