      "content": "探索城市社会治理的数字化创新路径来源：光明日报作者：王杨2026-10-19 14:21:29人民城市人民建，人民城市为人民。“十五五”规划纲要提出，“推动城市发展方式转变，建设创新、宜居、美丽、韧性、文明、智慧的现代化人民城市”。《中共中央国务院关于推动城市高质量发展的意见》提出，加强城市社会治理。人民城市社会治理的数字化创新，绝非简单的技术叠加，而是立足社会治理的民生属性，将以人民为中心的理念贯穿技术研发、平台搭建、应用落地全过程，实现社会治理现代化转型，筑牢现代化人民城市建设的社会根基。1.全维度数智感知助力了解社情民意城市是人民美好生活的载体，人民群众是城市建设的主体和城市发展的动力源泉。习近平总书记指出：“城市的核心是人，城市工作做得好不好，老百姓满意不满意、生活方便不方便，是重要评判标准。要坚持以人为本，不断完善城市功能，提高群众生活品质。”人民城市社会治理把人民群众的获得感、…"
