      "content": "习近平致信祝贺湖南大学建校100周年来源：新华网2026-10-16 10:32:14新华社北京10月16日电　中共中央总书记、国家主席、中央军委主席习近平16日致信祝贺湖南大学建校100周年，向全体师生员工和广大校友致以祝贺。习近平在贺信中强调，新起点上，希望湖南大学以新时代中国特色社会主义思想为指导，继承光荣革命传统，赓续千年书院学脉，弘扬“实事求是、敢为人先”的精神，不断提升办学质量和水平，努力培养更多经世致用的优秀人才，为建设教育强国、推进中国式现代化作出新贡献。湖南大学创办于1926年，具有千年历史的岳麓书院位于其校园内。100年来，学校坚持传承创新，为国家培养了大批优秀人才。扫描二维码分享到手机网站编辑 - 闫一涵 张盼 审核 - 刘小畅【网站声明】习近平致信祝贺湖南大学建校100周年"
