      "content": "从外资流向看中国市场新引力——正确认识中国经济的阶段特征与长远趋势来源：人民日报作者：周泽将2026-10-16 14:05:02新技术加快落地，创新生态不断完善，绿色发展释放机遇，制度型开放稳定预期，正在共同塑造中国经济的新引力近期，新一批重大外资项目密集投产。广东佛山，德国企业赛威投资超百亿元的华南智能制造基地开始运营；江苏昆山，美国汽车零部件供应商天纳克的全球创新中心启用。外资加速投向新产业、新赛道，彰显中国仍是全球投资热土。今年前8个月，全国实际使用外资金额同比有所下降，有人质疑，中国市场是否已经失去了吸引力？判断市场成色，不能只看一时的数量增减，更要看预期、看趋势。循着长期视角观察，能够更好读懂外资仍然看好中国的逻辑。追加投资最有说服力。今年上半年，近4800家外资企业追加对华投资。华南美国商会此前调查显示，75%的受访企业计划年内对华再投资。这说明中国市场具有长期吸引力，深耕中…"
