      "content": "让医疗康复护理服务沉下去、暖起来来源：光明日报作者：崔华前 王明迪2026-10-16 14:05:04一场手术之后，患者需要功能康复：慢性病患者需要长期照护；失能老人离不开专业照料……医疗康复护理的痛点，往往不在于有没有，而在于是否便利。近日，国家卫生健康委、国家发展改革委印发《医疗康复护理扩容提升工程实施方案》，着力健全医疗康复护理服务体系，推动优质康复护理资源下沉，让更多群众在家门口享有贴心可及的健康照护，让康复护理服务真正沉下去、暖起来。长期以来，医疗康复护理资源集中在大城市三级医院，基层和社区能力相对薄弱，患者出院后往往陷入医院管不了、社区接不住、家庭扛不起的困境。方案提出，“健全以二级医院为主体、基层医疗卫生机构为网底、三级医院指导支持、其他医疗卫生机构共同参与的康复护理服务网络”，“力争到2030年，每千人口康复护理床位数达到0.48张左右，人口较多、老龄化程度较深、康复护理…"
