      "content": "擦亮农业防灾减灾科技底色来源：科技日报作者：易可可 马欣2026-10-15 10:55:558月16日，习近平总书记在《求是》杂志发表重要文章《提高防灾减灾救灾能力》，指出要“深入开展自然灾害基础研究，努力把握自然灾害形成演变规律”。全球气候变化正在改变农业气象灾害的强度、发生季节和地域分布，高温热浪、干旱、暴雨洪涝等灾害的复合性和连续性更加突出。作物生产受农业气象灾害影响大，具有生育阶段敏感、农时约束严格、区域差异明显等特点，受灾后的产量和品质损失往往难以在当季追回。体系化布局农业灾害重大科学基础设施，深入研究极端环境下农业生物响应和灾害演变机理，是提高农业抗灾能力、保障粮食和重要农产品稳定安全供给的重要支撑。积极应对复合型灾害挑战全球气候变化正在改变农业气象灾害的发生条件。平均气温上升改变了作物物候和农业生产的气候背景，一些地区高温热浪、季节性干旱和强降水过程的发生强度与时间分布出现…"
