      "content": "习近平向第140届中国进出口商品交易会致贺信来源：新华网2026-10-14 16:30:38新华社北京10月14日电　10月14日，国家主席习近平向第140届中国进出口商品交易会（广交会）致贺信。习近平指出，广交会创办70年来，在促进中外贸易往来方面发挥了重要作用，已成为中国扩大高水平对外开放、推动建设开放型世界经济的有效平台。新形势下，中国愿同世界各国携起手来，共同维护多边贸易体制，保障全球产业链供应链稳定畅通，拓展国际经贸互利合作空间，推进普惠包容的经济全球化，为世界发展繁荣持续注入新动力。第140届广交会当日在广东省广州市开幕，由商务部和广东省人民政府共同主办。扫描二维码分享到手机网站编辑 - 王慧 张盼 审核 - 于波【网站声明】习近平向第140届中国进出口商品交易会致贺信"
