      "content": "求是网评论员：推动新质生产力发展取得更大实效来源：求是网作者：求是网评论员2026-10-14 20:08:59生产力是人类社会发展的根本动力。近日，中共中央、国务院印发《关于发展新质生产力的意见》，提出19条重大发展改革任务，充分彰显了以习近平同志为核心的党中央对发展新质生产力的高度重视，为推动“十五五”和今后一个时期经济社会高质量发展提供了重要行动指南。近年来，围绕发展新质生产力，各地区各部门高度重视、积极实践，取得显著成效。我国自主创新能力不断增强，科技创新和产业创新持续深度融合，与新质生产力更相适应的生产关系加快完善。今年上半年，以高端制造等为代表的新动能对我国经济增长的贡献率超过四成，新质生产力展示出对高质量发展的强劲推动力、支撑力。但也要看到，当前在发展新质生产力的实践中，出现了一些苗头性问题。有的片面认为发展新质生产力就是抓新兴产业、未来产业，忽视传统产业升级改造，把传统产业…"
