      "content": "“红星照耀中国·新长征再出发”网络主题宣传活动在江西于都举行来源：新华网作者：记者余贤红2026-10-14 22:06:22新华社南昌10月13日电（记者余贤红）13日，由中央网信办、中央党史和文献研究院、新华通讯社、江西省委网信委共同主办的“红星照耀中国·新长征再出发”网络主题宣传活动在江西于都县举行。中央宣传部副部长、中央网信办主任、国家网信办主任庄荣文，中央党史和文献研究院院长曲青山，江西省委书记、省人大常委会主任尹弘，新华社副社长、党组成员刘健出席活动并致辞。江西省委常委、省委宣传部部长卢小青主持活动政务环节。活动以《七律·长征》开场，红军烈士后代、红色宣讲员、文艺工作者等通过可视化呈现、故事化叙事、沉浸式演绎、互动化表达，讲述红军不怕远征难的动人故事，彰显革命理想高于天的信仰力量。全国道德模范、科研工作者、名古屋亚运会冠军代表、青少年学生以及相关领域干部群众代表等，结合各自经历…"
