      "topics": [],
      "content": "长征凭什么铸就伟大来源：浙江宣传微信公众号作者：之江轩2026-10-14 11:16:2510月9日，60集重大革命题材电视剧《伟大的长征》在央视一套黄金档开播。对照剧名中的“伟大”，长征的开篇似乎算不上恢弘：队伍越打越少，根据地越丢越小，就连落脚方案也先后七次改变，直到第八次才选定陕北。但就是这样一支队伍，完成了震撼世界的伟大远征：1934年10月至1936年10月，中国共产党领导工农红军翻越冰山雪岭，穿越沼泽草地，纵横十余省，长驱二万五千里。中央红军从出发时的8.6万余人，抵达陕北时仅剩七千余人。正是这七千多人，把中国革命的火种带到陕北，推向全民族抗战的前线。美国记者埃德加·斯诺在《红星照耀中国》中评价：“长征是军事史上伟大的业绩之一。”这支队伍凭什么铸就伟大？今天，我们不妨重温三句经典论断，读懂长征的精神密码。一、“长征是宣言书，长征是宣传队，长征是播种机”1935年12月27日，…"
