      "content": "以投资优化支撑产业升级——正确认识中国经济的阶段特征与长远趋势③来源：人民日报作者：刘元春2026-10-14 11:08:59把资源投向补短板、增后劲的关键领域，让投资更好服务新质生产力发展和现代化产业体系建设，把投资成效最终体现到就业扩大、收入增长、生活改善上浙江开工建设1000千伏特高压交流环网工程；江苏南京投入运行国内首个Pre6G试验网；广东阳江将算力中心“潜入”海底，依托海上风电实现绿电直供……今年以来，各地踊跃推进“六张网”建设，以拓展有效投资夯实发展基座。投资是当下的需求，也是未来的供给。如何看待当前的投资形势、预判未来的投资走势？这需要用系统思维把握投资运行的阶段性特征与结构性变化，把握短期波动与长期趋势的辩证关系，把握有效投资空间与资金供给基础的支撑条件。唯有如此，才能不被短期的数据起伏所干扰，透过总量变化看到结构优化，透过增速回落看到动能转换，从而得出客观理性的判断。…"
