      "content": "发展新时代中国特色社会主义文化的科学指引——学习《习近平文化文选》第一卷、第二卷来源：人民日报作者：齐卫平2026-10-14 11:08:10文化繁荣兴盛是中国式现代化的重要标志，中国特色社会主义文化是激励全党全国各族人民奋勇前进的强大精神力量。习近平总书记作出发展新时代中国特色社会主义文化的重大部署并提出重要要求。《习近平文化文选》第二卷中，习近平总书记指出：“我们要锚定二〇三五年建成文化强国的战略目标，坚持马克思主义这一根本指导思想，植根博大精深的中华文明，顺应信息技术发展潮流，不断发展具有强大思想引领力、精神凝聚力、价值感召力、国际影响力的新时代中国特色社会主义文化，不断增强人民精神力量，筑牢强国建设、民族复兴的文化根基。”《习近平文化文选》第一卷、第二卷收入的习近平总书记重要著作，以丰富的内容、深邃的思想、完整的体系和严谨的学理，系统回答了新时代坚持和发展什么样的中国特色社会主义…"
