      "content": "习近平总书记为健康中国建设取得决定性进展指明方向来源：新华网2026-10-14 09:36:32时隔10年，全国卫生与健康大会再次召开。习近平总书记在会上发表重要讲话，总结新时代以来我国卫生与健康事业发展的成就和经验，分析面临的形势，部署一系列重大任务。到2035年建成健康中国，是党中央作出的一项战略决策。“十五五”是实现这一目标的关键时期。开局之年，习近平总书记深刻回答了健康中国建设的根本性、方向性、全局性问题，为做好新时代新征程卫生与健康工作指明了方向、提供了重要遵循。围绕健康中国建设，总书记首次系统阐明六大能力——“应当具有强大的健康管理能力、疾病防控能力、医疗服务能力、医保支撑能力、医药创新能力、人才培养能力”。健康管理能力，重在“治未病”。从“引导全社会树立正确健康观”到“引导广大青少年养成良好的学习生活习惯”，从“鼓励和支持全民健身、健康休闲”到“守护好‘舌尖上的安全’”，习…"
