      "content": "习近平出席全国卫生与健康大会并发表重要讲话来源：新华网2026-10-13 14:11:52习近平在全国卫生与健康大会上强调坚定不移走中国特色卫生与健康发展道路确保“十五五”时期健康中国建设取得决定性进展李强讲话　赵乐际王沪宁蔡奇丁薛祥李希出席10月12日至13日，全国卫生与健康大会在北京召开。中共中央总书记、国家主席、中央军委主席习近平出席会议并发表重要讲话。新华社记者 谢环驰 摄新华社北京10月13日电　全国卫生与健康大会12日至13日在北京召开。中共中央总书记、国家主席、中央军委主席习近平出席会议并发表重要讲话。他强调，“十五五”时期是实现到2035年建成健康中国目标的关键时期，要坚定不移走中国特色卫生与健康发展道路，贯彻新时代卫生与健康工作方针，扬优势、固基础、补短板、强弱项，推动卫生与健康事业高质量发展，不断提高人民健康水平，确保健康中国建设取得决定性进展。李强作总结讲话。赵乐际…"
