      "content": "习近平同博茨瓦纳总统博科会谈来源：新华网作者：记者 曹嘉玥2026-10-13 20:59:0010月13日下午，国家主席习近平在北京人民大会堂同来华进行国事访问的博茨瓦纳总统博科举行会谈。这是会谈前，习近平和夫人彭丽媛在人民大会堂北大厅为博科和夫人卡奥内举行欢迎仪式。新华社记者 谢环驰 摄新华社北京10月13日电（记者曹嘉玥）10月13日下午，国家主席习近平在北京人民大会堂同来华进行国事访问的博茨瓦纳总统博科举行会谈。两国元首宣布将双边关系提升为全面战略合作伙伴关系。习近平指出，上世纪70年代，博方在两国建交前就投票支持新中国恢复在联合国合法席位。如今双方在共逐现代化梦想道路上携手前行，续写中博友谊新篇章。中博友谊要像钻石般璀璨恒久。双方要铭记相依相扶的“来时路”，走好新时代中博关系发展的“康庄道”，为世界发展和进步贡献力量。习近平强调，“志同”才会“道合”。今年是中国共产党成立105周…"
