      "content": "求是网评论员：坚定不移走中国特色卫生与健康发展道路来源：求是网作者：求是网评论员2026-10-13 21:09:19人民健康是民族昌盛和国家强盛的重要标志。10月12日至13日，全国卫生与健康大会在北京召开，习近平总书记出席会议并发表重要讲话，深刻回答了卫生与健康工作一系列根本性、方向性、全局性问题，具有很强的思想性、战略性、指导性，为做好新时代新征程卫生与健康工作提供了重要遵循。我们党历来高度重视人民健康。党的十八大以来，习近平总书记多次强调，“现代化最重要的指标还是人民健康”，“人民健康既是民生问题，也是社会政治问题”。以习近平同志为核心的党中央始终把保障人民健康放在优先发展的战略位置，确立新时代卫生与健康工作方针，作出建设健康中国的重大决策部署，建成世界上规模最大的医疗服务体系、传统医药体系、疾病防控体系、医疗保障体系，居民主要健康指标持续向好，卫生与健康事业取得历史性成就、实现全…"
