      "content": "把家风建设作为领导干部作风建设重要内容来源：中国纪检监察报作者：郝思斯2026-10-13 10:56:01“焦裕禄同志曾经亲自起草了《干部十不准》，规定干部在任何时候都不搞特殊化。他得知儿子‘看白戏’，立即拿出钱叫儿子到戏院补票。”在《习近平党建文选》第一卷《做焦裕禄式的县委书记》中，习近平总书记生动讲述了焦裕禄严于律己、严于治家的好家风。学习领悟《习近平党建文选》第一卷、第二卷，领导干部要深刻领悟家风建设之于严正党风政风的重要意义，清白做人、勤俭齐家、干净做事、廉洁从政，管好自己和家人，涵养新时代共产党人的良好家风。领导干部的家风，不是个人小事、家庭私事，而是领导干部作风的重要表现。对此，习近平总书记高度重视，反复告诫。在《在第十八届中央纪律检查委员会第六次全体会议上的讲话》（《习近平党建文选》第一卷篇目）中，习近平总书记引用了“将教天下，必定其家，必正其身”“莫用三爷，废职亡家”“心…"
