      "content": "推动形成文化遗产大保护格局来源：光明日报作者：刘江红2026-10-13 10:55:59文化遗产是中华文明赓续传承的重要载体，是中华民族的情感维系和精神标识。近日，中共中央办公厅、国务院办公厅印发《文化遗产保护传承“十五五”规划》（以下简称《规划》），提出“到2030年，文化遗产资源全面摸清，监管体制基本理顺，法规制度更加健全，人才队伍持续壮大，保护督察有力有效，文化遗产大保护格局基本形成，文化遗产在建设社会主义文化强国中的重要作用充分彰显”，标志着我国文化遗产保护传承正迈向高质量发展新阶段。文化遗产大保护格局彰显“大历史观”“大遗产观”。从文化遗产、工业遗产、农业遗产、水利遗产等分类保护，到物质遗产与非物质文化遗产、文化遗产与自然遗产协同保护；从考古和文明历史研究，到党领导人民在革命、建设、改革和新时代伟大实践中的历史物证；从博物馆、考古遗址、非遗工坊、历史文化名城名镇名村到线性遗产、…"
