      "content": "数智融合提升全要素生产率——加快发展先进制造业①来源：经济日报作者：记者 黄 鑫2026-10-12 14:32:46近期举办的全国先进制造业大会提出，要顺应新一轮科技革命和产业变革趋势，以新一代智能制造为主攻方向，发展策略上更加注重数智赋能，着力推动制造业智能化、绿色化、融合化发展。其中，智能化是先进制造业的核心引擎，也是培育新质生产力的重要抓手。智能化是指用数字技术、人工智能重构研发、生产、质控、运维全链条，推动制造业从经验驱动转向数据驱动。国研新经济研究院创始院长、智能经济首席专家朱克力认为，智能化是保障产业链自主可控的关键抓手。依托数字孪生、工业大模型，可以加快国产装备、工业软件迭代，在关键环节减少外部依赖，筑牢产业安全底座。同时，智能化能联动绿色化、融合化，通过智能调度优化能耗，实现降本减碳；依托数字平台打通制造端与市场端，实现个性化定制、服务型制造等。赛迪研究院政策法规研究所所…"
