      "content": "推动国家通用语言文字推广普及走深走实来源：兵团日报作者：韩生辉2026-10-12 16:39:02推广普及国家通用语言文字是关乎国计民生的基础性事业，是铸牢中华民族共同体意识的重要途径。2026年1月1日起，新修订的《中华人民共和国国家通用语言文字法》（以下简称《国家通用语言文字法》）正式施行，为推广普及国家通用语言文字提供了坚实法治保障。我们要以新修订的《国家通用语言文字法》为遵循，坚持法治引领、学校筑基、社会面推广普及，推动国家通用语言文字推广普及走深走实。坚持法治引领，把握核心要义新修订的《国家通用语言文字法》巩固了国家通用语言文字的法律地位，完善了一系列制度安排，其核心要义体现在三个方面。一是明确权利保障。新修订的《国家通用语言文字法》第四条明确规定：“公民有学习和使用国家通用语言文字的权利。任何组织或者个人都不得妨碍公民学习和使用国家通用语言文字。国家为公民学习和使用国家通用语…"
