      "content": "从三星堆感悟中华民族的创造力来源：人民日报作者：人民日报评论部2026-10-12 09:06:39（一）“推动高质量发展，文化是重要支点”“战胜前进道路上各种风险挑战，文化是重要力量源泉”。10月9日，学习《习近平文化文选》第一卷、第二卷座谈会在京召开。研读《习近平文化文选》，要切实把学习成效转化为加快推进文化强国建设的实际行动。9月底，“三星堆文物怎么还有火锅”登上热搜。三星堆火锅产业大会在四川广汉举行，这份“热辣滚烫”仍在创新发展。前不久，全国首家“中子文化遗产保护实验室”成立。有中子技术助力，包括三星堆在内的更多古老创造将被更好“解码”。放宽视野，文创变身新年货，“村超”带动一域火，文化“新三样”出海圈粉……当古老的文化基因遇上当代的创造活力，中国正把传统做成最潮的爆款。新思想引领中华文化在新时代展现万千气象，可以从血脉基因、思想激发、融合赋能三个维度，深刻感悟中华民族的创造力。（…"
