      "content": "上下协同稳投资要把握三个维度来源：经济日报作者：金观平2026-10-09 09:25:06近期召开的国务院常务会议研究宏观政策发力提效、促进有效投资有关工作，指出“要上下协同合力稳投资”。在当前投资增长承压的背景下，“上下协同”四个字既点出了问题的关键，也指明了破题的方向。今年前8个月，全国固定资产投资同比下降7.2%，降幅有所扩大。投资下行，折射出我国经济正在经历深刻的结构调整、动力转换。一方面，传统领域投资的转型升级需求迫切；另一方面，新的投资增长点加速孕育，但不少投资项目涉及多层级、多领域、多主体，对投资的精准性、协同性提出了更高要求。做好“上下协同”，至少包含3个维度。纵向维度，要充分调动中央和地方两个积极性。中央层面，今年“两重”建设项目清单已全部下达完毕，安排8000亿元超长期特别国债资金支持1417个重大项目建设；新型政策性金融工具总规模从去年的5000亿元增加到8000亿…"
