      "content": "始终保持党同人民群众的血肉联系来源：中国纪检监察报作者：张琰2026-10-08 12:04:38我们党来自人民、植根人民、服务人民，党的根基在人民、血脉在人民、力量在人民。在《习近平党建文选》第一卷、第二卷中，习近平总书记强调，加强作风建设，必须紧紧围绕保持党同人民群众的血肉联系，增强群众观念和群众感情，不断厚植党执政的群众基础。保持党同人民群众的血肉联系，始终是我们党立于不败之地的根基。加强和改进作风建设核心是保持党同人民群众血肉联系。党的作风是党组织和党员在思想、工作、生活等方面表现出来的一贯态度和行为，反映的是形象和素质，集中表现为党同人民群众的血肉联系。我们党的最大政治优势是密切联系群众，党执政后的最大危险是脱离群众。在《习近平党建文选》第一卷《群众路线是党的生命线和根本路线》中，习近平总书记指出，在革命、建设、改革长期实践中，我们党始终要求全党同志坚持光荣传统、发扬优良作风，为…"
