      "content": "提升学生科学素养 夯实教育强国建设人才根基来源：光明日报作者：李晓强2026-10-06 14:32:20编者按经济合作与发展组织（OECD）近日发布2025年国际学生评估项目（以下简称PISA）测评结果。在参与测评的91个国家和地区中，中国内地学生在科学、数学、阅读以及计算问题解决能力方面的表现均位居前列，展现出我国基础教育的过硬质量与育人成效。作为当前最具国际影响力的大规模教育质量监测评价项目之一，PISA为我们从国际比较视角认识基础教育发展成效、分析现实问题和明确改进方向提供了重要参照。成绩令人振奋，但教育发展永无止境。如何汲取国际测评经验，持续深化教育改革、优化育人体系？本版约请专家进行深度解读。当今世界，新一轮科技革命和产业变革深入发展，人工智能、生命科学、新能源等领域不断取得突破。在此背景下，学生的科学素养既关系到国家的科技创新和国际竞争，也关系着每个人能否理解科学、用好科学。…"
