      "content": "“五十六个民族就是相亲相爱的一家人”来源：人民日报作者：记者 李昌禹 刘博通2026-10-04 11:35:52“我和我的祖国，一刻也不能分割……”金秋十月，新中国迎来77周年华诞。北京天安门广场、西藏拉萨八廓街、新疆伊犁六星街……一面面五星红旗迎风飘扬，《我和我的祖国》《歌唱祖国》等歌曲在各民族群众间传唱，各族儿女对伟大祖国真挚的爱在心底涌流。习近平总书记指出：“中华民族是一个大家庭，五十六个民族就是相亲相爱的一家人。”五十六个民族，同一个梦想，各民族像石榴籽一样紧紧抱在一起。目光所及、情感所向，铸牢中华民族共同体意识在大江南北生根，神州大地处处团结奋进、蓬勃向上，民族团结之花越开越绚烂。共同心声：做伟大祖国的守护者盛世华诞，礼赞祖国。家国认同，血脉相融。10月1日清晨，帕米尔高原，新疆塔什库尔干塔吉克自治县，海拔5000多米的红其拉甫国门前，上千名各族群众齐聚，见证五星红旗升起的神圣…"
