      "content": "加快建设强大国内市场来源：人民日报作者：金轩2026-10-04 11:52:01习近平总书记高度重视扩大内需，强调“要坚持以国内大循环为主体，正确处理消费和投资、需求和供给的关系”“让内需成为经济发展的主动力”。当前，外部环境复杂严峻，必须坚定实施扩大内需战略，以内需的稳定发展对冲外需的不确定性。“十五五”时期，全方位扩大内需、加快建设强大国内市场，对贯彻新发展理念、构建新发展格局、推动高质量发展具有重要意义。内需拉动经济增长的主动力、稳定锚作用持续彰显今年以来，各地区各部门认真贯彻落实党中央、国务院部署要求，坚定实施扩大内需战略，着力促消费稳投资，为经济平稳运行打下良好基础。今年上半年，内需对经济增长的贡献率为82.1%，其中最终消费支出、资本形成总额贡献率分别为46%、36.1%，内需拉动经济增长的主动力和稳定锚作用持续彰显。消费方面，丰富产品供给、创新消费场景，更好地满足多样化消费…"
