      "content": "为变乱交织的世界注入更多确定性和正能量——论学习贯彻习近平总书记在庆祝中华人民共和国成立77周年招待会上重要讲话来源：人民日报作者：评论员2026-10-04 11:36:06“我们要坚持独立自主的和平外交政策，推动落实四大全球倡议，推动构建人类命运共同体，为变乱交织的世界注入更多确定性和正能量。”在庆祝中华人民共和国成立77周年招待会上，习近平总书记铿锵有力的话语，展现中国共产党人为人类谋进步、为世界谋大同的天下情怀，彰显中国与世界共享机遇、共谋发展的大国担当。在历史前进的逻辑中前进、在时代发展的潮流中发展，中国始终把自身发展置于人类发展的坐标系中，始终把自身命运与世界各国人民命运紧密相连。“我们有坚定推进中国式现代化的决心，也有以高水平对外开放同世界共享发展机遇的胸怀，将以自身发展为全球经济增长注入信心和动力。”这是古老东方大国一步步迈向伟大复兴给世界带来的新气象、新塑造。“与中国同行…"
