      "content": "双向赋能锻造产业硬实力来源：经济日报作者：顾阳2026-10-03 11:23:24国家发展改革委近日召开专题新闻发布会，介绍推进服务业扩能提质有关情况，会上发布的一系列细化举措，精准聚焦制造业、服务业融合堵点，向市场各方传递出一个明确信号：制造业与服务业的深度融合，是稳住经济大盘、培育新质生产力、推动高质量发展的必答题，而非选择题。长期以来，我国产业发展存在明显的“割裂惯性”——制造业与服务业在各自的赛道上各干各的。比如，一些制造企业陷入“重生产、轻服务”的路径依赖，扩产能、抓生产很在行，但在研发创新、供应链管理、售后增值服务等方面却有明显短板，企业因此常年徘徊在产业链低端的加工环节，经营利润薄且抗风险能力不强。与此同时，部分服务企业游离在实体经济这个主战场之外，高端生产性服务供给不足，服务专业化水平也不高，难以适配先进制造业数智化进阶的新要求。客观上看，近年来经济全球化步伐不断加快，上…"
