      "content": "谱写构建中文命运共同体新篇章来源：人民日报作者：陈少春2026-10-02 16:39:319月30日，习近平主席同文莱苏丹哈桑纳尔互致贺电，庆祝两国建交35周年。文莱北濒南海，素有“和平之邦”和“婆罗洲明珠”美誉。中文传统友谊源远流长、历久弥坚，两国在携手现代化进程中树立了大小国家相互尊重、平等相待、共同发展的典范。建交35年来，中文政治互信不断深化，各领域合作成果丰硕，人文交流更加密切。元首领航，锚定前行方向。元首引领是中文关系快速发展的根本保障。2013年以来，习近平主席和哈桑纳尔苏丹多次会见会谈，建立了深厚互信和诚挚友谊，从战略高度和长远角度为双边关系把舵定向，引领中文关系不断实现历史性跨越。2013年，两国元首决定建立中文战略合作关系。2018年11月，习近平主席对文莱进行国事访问，两国关系提升为战略合作伙伴关系。2025年2月，习近平主席同来华进行国事访问的哈桑纳尔苏丹举行会谈…"
