      "content": "推动算电协同 夯实智能经济绿色底座来源：光明日报作者：包倩文2026-09-30 09:25:59当前，新一轮科技革命和产业变革加速演进，人工智能成为推动经济结构变革和生产力跃升的重要力量，同时也是推动绿色发展的重要技术力量。依托数据分析、智能感知、预测优化和动态决策，人工智能可以提高工业生产、能源调度、交通运输、建筑运行等领域的资源配置效率，降低单位产出能耗强度，加快推进能源体系绿色低碳转型。然而，智能技术的绿色赋能必须以持续稳定的算力供给为前提，算力的形成和运行又离不开电力支撑。随着大模型训练、智能体应用和数据中心建设持续推进，推动算力系统与能源电力深度融合，促进智能经济发展与能源绿色转型相互支撑，正成为培育绿色生产力、塑造智能经济竞争新优势的重要着力点。2026年《政府工作报告》提出，“实施超大规模智算集群、算电协同等新基建工程”。“十五五”规划纲要也明确提出，“推动绿色电力与算力协…"
