      "content": "健全农民教育培训内容体系来源：农民日报作者：孙静茹2026-09-30 10:54:25党中央、国务院高度重视乡村人才培养，习近平总书记强调，“要推动乡村人才振兴，把人力资本开发放在首要位置”。党的二十届四中全会提出“坚持投资于物和投资于人紧密结合”的要求。《加快农业农村现代化“十五五”规划》及2026年中央一号文件对发展壮大乡村人才队伍作出部署。这为做好新形势下农民教育培训工作提供了遵循、指明了方向。健全教育培训内容体系是农民教育培训的基础性工作。“十五五”时期，发展壮大乡村人才队伍、提升农民能力素质，应以服务保障国家粮食安全、发展富民乡村产业、创造乡村优质生活空间为主要任务，完善顶层设计，促进内容供给与农民需求精准衔接，推动党中央决策部署贯彻落实。教育培训农民会种粮种好粮，保障粮食和重要农产品有效供给宣贯扶持政策，给农民吃上“定心丸”。粮食安全政策具有引导粮食生产、优化农业结构、保护农…"
