      "content": "中美达成八点成果共识来源：新华网2026-09-26 16:13:09新华社华盛顿9月25日电　当地时间9月23日至25日，中国国家主席习近平对美国进行国事访问。其间，两国元首就中美建设性战略稳定关系及重大国际地区问题深入交换意见，达成八点成果共识，包括：一、双方同意构建“基于尊重、公平、对等的中美建设性战略稳定关系”。二、双方同意相互支持对方办好亚太经合组织（APEC）领导人非正式会议和二十国集团（G20）领导人峰会。两国元首有意出席对方主办的会议。三、两国元首同意伊朗应履行不发展核武器的承诺，任何国家或机构都不得对国际水道征收通行费。四、两国元首忆及中国和美国是二战盟友，并肩作战赢得战争胜利。五、两国元首认可中美经贸磋商机制积极作用和双方经贸团队磋商成果，包括建立并推进贸易理事会等机制，达成“300亿美元”对等降税安排，延期吉隆坡经贸磋商成果等，并指示予以落实。六、中美禁毒执法部门合作…"
