      "content": "特朗普在白宫欢迎仪式上的讲话来源：新华网2026-09-25 16:15:03新华社华盛顿9月24日电　当地时间9月24日上午，美国总统特朗普在白宫举行隆重仪式，热烈欢迎中国国家主席习近平对美国进行国事访问。特朗普在白宫欢迎仪式上的讲话内容如下：习近平主席、彭丽媛女士，中国代表团的各位成员，非常高兴欢迎大家来到美丽的白宫，我们深感荣幸。今年5月，我有幸访问北京，中方给予隆重热情接待。今天，我和梅拉尼娅非常荣幸在华盛顿接待两位来访。2016年我首次当选美国总统以来，我同习近平主席建立了以相互尊重和两国人民根本利益为基础的伟大友谊。我与习近平主席在德国、阿根廷、日本、韩国以及北京、佛罗里达棕榈滩等世界各地多次会晤。今天，我们首次相聚白宫。正如习近平主席已经看到的那样，同您上次来访相比，如今的白宫已经发生了很大变化。习近平主席和彭丽媛女士此次来访，恰逢美国独立250周年的重要时刻。明天，我们将参…"
