      "content": "求是网评论员：推动中美建设性战略稳定关系行稳致远来源：求是网作者：求是网评论员2026-09-25 15:23:24当地时间9月23日，习近平主席抵达华盛顿，应美国总统特朗普邀请，对美国进行国事访问。两国元首在半年内实现国事互访，在中美关系和国际关系中具有里程碑意义。习近平主席强调，“实现中华民族伟大复兴和让美国再次伟大，完全可以并行不悖、相互成就、造福世界”，这一重要论述洞察历史大势、彰显战略智慧，为中美走好大国正确相处之道注入信心、指明方向。中国和美国都是伟大的国家，中国人民和美国人民都是伟大的人民。作为世界前两大经济体，中美两国经济总量超过世界三分之一，双边货物贸易额约占世界五分之一，今年上半年，中美货物贸易总值达2万亿元人民币。紧密的经贸联系体现两国利益深度交融，是中美关系的压舱石和推进器。今年5月，习近平主席同特朗普总统在北京举行会晤，共同确立了构建中美建设性战略稳定关系的新定位…"
