      "content": "长征是一次理想信念的伟大远征来源：光明日报作者：张树军2026-09-25 11:28:30习近平总书记指出，长征是一次理想信念的伟大远征。崇高的理想、坚定的信念永远是中国共产党人的政治灵魂。中国共产党从成立之日起，就把共产主义确立为远大理想，始终团结带领中国人民朝着这个伟大理想前行。党和红军几经挫折而不断奋起，历尽苦难而淬火成钢，归根到底在于心中的远大理想和革命信念始终坚定执着、始终闪耀着火热的光芒。理想信念是我们读懂长征史诗的一把总钥匙，也是我们今天传承红色基因、赓续红色血脉、走好新时代长征路的强大精神动力。红军何以在绝境中杀出一条生路，最终取得胜利？答案就在于共产党人根植于灵魂深处的理想信念。红军长征的年代，中国处在半殖民地半封建社会的黑暗境地，社会危机四伏，日本野蛮侵略，国民党反动派置民族危亡于不顾，对南方各个革命根据地连续发动大规模“围剿”。中国共产党敏锐地认识到，中华民族最大的…"
