      "content": "这份倡议，关乎中美关系的未来来源：人民日报作者：记者 黄 超2026-09-25 11:28:30“这里，我愿宣布，未来5年，中方将邀请10万名美国青少年来华交流学习。”当地时间9月24日上午，习近平主席出席美国总统特朗普在白宫举行的欢迎仪式时表示。太平洋的风浪之间，总有一股相向而行的暖流。现场，习近平主席深刻揭示两国关系发展的根基所在——“中美关系希望在人民、未来在青年。”2023年11月，习近平主席访美期间宣布，“中方未来5年愿邀请5万名美国青少年来华交流学习”；2026年5月，复信参加“共航蔚蓝：中美青年友谊行”活动的两国学生表示，“提前两年半实现预期目标”……不到3年时光，“5年5万”倡议绘就一幅跨越大洋的青春长卷。犹记倡议提出不久，大洋彼岸老朋友的一封真挚来信，让友谊的种子跨越山海接续扎根。曾于1985年接待时任河北正定县委书记习近平访问艾奥瓦州马斯卡廷市的美国友人萨拉·兰蒂致信…"
