      "content": "以安全治理护航人工智能产业创新来源：经济日报作者：刘景芝 张 莹2026-09-25 15:05:162026年国家网络安全宣传周不久前落幕。宣传周期间发布的《人工智能安全治理框架3.0》，延续“风险分类、技术应对、综合治理”的核心逻辑，为智能时代的安全治理提供了又一份系统性方案，对提升AI安全治理共识和风险防范应对能力具有重要意义。不同于以内容生成为主的传统大模型，智能体具备自主感知、规划任务、调用工具、执行操作的能力，其与科研制造、民生服务、社会治理等诸多领域深度融合，成为推动产业数字化向纵深发展的关键。当前，伴随着AI的大规模商业化应用，AI驱动的网络攻击安全风险也日趋凸显。AI网络攻击具有智能化、自动化、隐蔽化特点，攻击对象从服务器、网络边界拓展至大模型、智能体、核心数据，权限调用、工具执行等环节也成为风险突破口，防护难度显著增加。一旦安全失守，不仅单个企业遭受损失，更可能动摇整个…"
