      "content": "求是网评论员：人工智能何以引领数字贸易创新发展来源：求是网作者：求是网评论员2026-09-24 19:17:09金秋九月，潮涌钱塘。9月23日至27日，第五届全球数字贸易博览会在杭州举行。本届数贸会以“在数贸会遇见AI未来”为年度主题，人工智能参展企业占比超1/3，率先设立词元专区，集中展示算力底座、大模型服务、行业应用的全链条创新生态，生动展现人工智能“可贸易”与“赋能贸易”的双重价值。这场国家级国际性盛会，既是观察我国数字贸易发展的重要窗口，也生动诠释出人工智能正在成为驱动数字贸易创新发展的核心引擎。过去，我们讲数字贸易，想到的是跨境电商卖货、数字文化产品对外输出。人工智能的深度融入，正在从底层改变贸易的生产要素、交易方式和价值实现路径。从研发生产到市场推广、供需对接再到交付结算，人工智能正加速重塑数字贸易整个链条，推动数字贸易从输出商品和服务，升级为输出技术能力、服务能力。世贸组织…"
