      "content": "构建普惠包容的数字贸易体系来源：经济日报作者：金观平2026-09-24 10:09:13当前，数字贸易已成为拉动全球经济增长的重要引擎。9月23日至27日，第五届全球数字贸易博览会在杭州召开，为全球数字技术与国际贸易融合发展提供了展示窗口。近年来，全球数字贸易增长强劲，但红利分配并不均衡。数据显示，可数字化交付服务过去10年年均增长7.1%，已占全球服务出口的56%。然而，最不发达经济体可数字化交付服务仅占其服务出口的16%，发达经济体则为61%。人工智能的算力、数据、金融和专业能力高度集中于少数经济体，不少发展中国家尚未制定国家人工智能战略。因此，能否实现普惠红利，成为推动数字贸易持续发展的关键。我国数字贸易蓬勃发展，为全球数字贸易增长作出积极贡献。2025年，我国可数字化交付的服务进出口总额超4323亿美元，同比增长6.3%。本届数贸会上，人工智能参展企业占比超过三分之一，率先设立词…"
