      "content": "中美关系的根基由人民浇筑，未来靠青年创造来源：人民日报作者：记者 马 菲 包 晗2026-09-24 13:59:35“中美青年同处一个地球，共担时代使命。”近日，习近平主席复信来华参加中美青年主题交流活动的美国10所高校青年学生，并对两国青年携手成为中美友好合作的传承者、维护者、发展者提出殷切期望。近年来，中美人文交流形式不断丰富、机制日益完善，逐步形成多层次、广覆盖的交往格局，成为推动大国关系良性互动的重要力量。赓续情谊，筑牢民间友好历史根基“中美关系的根基由人民浇筑，未来靠青年创造。”今年4月，中美“乒乓外交”55周年纪念大会暨中美青少年体育交流系列活动启动仪式举行，习近平主席致贺信，为新时代中美人文交流发展明确方向。民间友好始终是中美关系发展的温暖底色。1971年，美国乒乓球队历史性访华，“小球转动大球”的创举敲开了中美两国人民友好往来的大门，成为载入史册的民间外交佳话。彼时，年仅…"
