      "content": "扇动的翅膀自有力量来源：人民日报作者：匡 吉2026-09-24 13:59:17前段时间，第九届鲁迅文学奖颁奖典礼在上海举行。58岁的外卖骑手王计兵凭借诗集《低处飞行》站上领奖台，成为该奖历史上首位以外卖骑手身份获奖的诗人。“不是所有的翅膀都可以展翅高飞，”他在获奖感言中说，“低处的飞行也是飞行。”这句话，不只是诗意的表达，更是对奋斗价值的朴素诠释，是对世俗成功标准的重新审视。现实生活中，人们常常以为只有登顶才算成功，只有站在高处、拥有光环才值得喝彩。这种认知窄化了成功的维度，也低估了无数普通人坚守与奔跑的意义。事实上，飞行的价值，从来不止于抵达的高度，更在于不曾停歇、奋力向前的姿态。飞行中的坚守，无声亦有力量。2018年，外卖小哥雷海为凭借深厚诗词积淀，夺得《中国诗词大会》第三季总冠军。“外卖小哥”与“诗词达人”，两种身份融为一体，恰恰印证了一个道理：人生不能被职业标注，而是因追梦而精…"
