      "content": "求是网评论员：基础研究：如何把握自主和开放的关系来源：求是网作者：求是网评论员2026-09-23 08:31:04在《求是》杂志新近刊发的《在加强基础研究座谈会上的讲话》中，习近平总书记深刻指出：“探索世界科学前沿，国际合作必不可少。要主动融入全球创新网络，在开放合作中提升原始创新能力。”科学无国界，基础研究的重大突破日益依赖全球智慧的同频共振。在科技竞争与合作交织的背景下，以开放合作提升自主创新能力，关键在于把握好自主与开放的辩证统一关系，让自主为开放提供底气，让开放为自主注入活力，二者共同服务于提升原始创新能力这一根本目标。基础研究的关键发现、重大创新要不来、买不来、换不来，必须靠自己。特别是对我国这样的大国来说，无论是实现高水平科技自立自强、还是推动新质生产力发展，都必须坚持以我为主、自力更生。长期以来，正因为我国坚持基础研究自主可控，着力提升原始创新能力，才涌现出单原子催化、化学…"
