      "content": "加强人工智能同保障和改善民生深度结合来源：人民日报作者：刘知远2026-09-23 10:30:01今年7月，习近平主席在2026世界人工智能大会暨人工智能全球治理高级别会议开幕式上提出：“全面促进人工智能科技创新、产业发展、场景应用”。早在2018年，习近平总书记就指出：“要加强人工智能同保障和改善民生的结合，从保障和改善民生、为人民创造美好生活的需要出发，推动人工智能在人们日常工作、学习、生活中的深度运用”。这些重要论述，深刻指明了人工智能发展的重要价值和应用导向。“十五五”规划纲要提出“全面实施‘人工智能+’行动”“充分发挥数智技术和数据要素对丰富人民生活、改善民生福祉的作用”。要坚持以人为本、智能向善，把人工智能深度运用放到保障和改善民生的全局中谋划推进，使人工智能发展始终朝着服务人民、造福人民的方向前进。中国式现代化，民生为大。推动人工智能深度运用，不能停留于技术迭代和产业扩张，…"
