      "content": "以教育强国战略引领高水平应用型大学建设来源：光明日报作者：张启鸿2026-09-23 10:30:02教育是强国建设、民族复兴之基。习近平总书记强调，要“加快一流大学和一流学科建设，推进产学研协同创新，积极投身实施创新驱动发展战略，着重培养创新型、复合型、应用型人才”。应用型大学是中国特色高等教育体系不可或缺的重要组成部分。按照我国高等教育分类发展布局，研究型、应用型、技能型高校承担着不同的功能和使命，应在不同领域、不同赛道发挥优势、办出特色。高水平应用型大学一头连接知识创新和人才培养，一头连接产业发展和社会需求，是培养应用型创新人才、促进科技成果转化、服务区域经济社会发展的重要力量。面向“十五五”，应用型大学要以教育强国战略为引领，坚守办学定位，对标“办学能力优质、服务区域经济社会发展优秀”的“双优”要求，立足特色，提质升级，主动服务中国式现代化建设。1.坚守育人初心，准确把握应用型大学…"
