      "content": "求是网评论员：在基础研究中，出成果和出人才是什么关系来源：求是网作者：求是网评论员2026-09-22 10:18:28基础研究既要出成果，又要出人才，人才本身就是成果。两者互为依托、相互成就。正确认识和把握其辩证关系，关键是要扭住“人才”这个重中之重。在《求是》杂志新近刊发的《在加强基础研究座谈会上的讲话》中，习近平总书记深刻指出，基础研究归根结底靠高水平人才，强调要一体推进教育科技人才发展，全方位做好培养、引进、使用工作，努力使基础研究人才数量充足、素质优良、结构合理。近年来，我国之所以能够推动基础研究取得一批重大原创性成果，关键在于涌现出一批能打硬仗的优秀科学家。从铁基高温超导体系的机理研究取得原创突破，到微分几何学两大核心猜想被成功证明，再到有“人造太阳”之称的全超导托卡马克核聚变实验装置（EAST）实现亿度千秒稳态高约束运行，每一项重大突破都离不开甘于奉献、协同攻关的科研人才团队…"
