      "content": "实施更加积极有为的宏观政策 不断巩固拓展经济稳中向好势头来源：《理论学习与探索》作者：杨志勇2026-09-22 18:22:04一、引言2026年是“十五五”开局之年。“十五五”时期是中国基本实现社会主义现代化承上启下的关键五年。“十五五”开好局、起好步，至关重要。2026年，中国继续实施更加有为的宏观政策，继续实施更加积极的财政政策和适度宽松的货币政策，为中国经济注入更多活力，不断巩固拓展经济稳中向好势头。2026年一季度国内生产总值同比增长5.0%，CPI同比增长0.9%。一季度一般公共预算收入同比增长2.4%，为近三年来最快，这是第一季度经济保持较快增速在财政收入上的反映。第一大税种增值税收入情况更值得关注。一季度国内增值税同比增长4.9%，是经济回稳向好的结果，也说明有税收收入支撑的经济增长是实实在在的。价格形势好转也助力税收收入增长，尤其是3月份工业生产者出厂价格由降转升，结束…"
