      "content": "构建中国数量经济学自主知识体系来源：光明日报作者：王文举2026-09-22 09:20:28数量经济学作为融合经济学理论、数学方法、统计分析等的交叉学科，是揭示经济运行规律、开展政策模拟、支撑宏观调控与产业决策的重要工具。然而，长期以来，我国数量经济学研究多沿用西方理论框架、经典模型与分析范式，在推动学科发展和经济研究的同时，也逐渐显现出制度适配性不足、本土理论缺失、研究脱离实际等短板。当前，我国正处在推进经济高质量发展、构建新发展格局、实现国家治理现代化的关键阶段，对精准化、科学化、本土化的数量经济研究需求愈发迫切。构建以马克思主义为指导、立足中国实践、彰显中国特色的数量经济学自主知识体系，打破西方学术范式路径依赖，既是我国数量经济学学科发展的根本方向，也是服务国家战略、回应现实需求的时代使命。构建中国数量经济学自主知识体系的紧迫性中国特色经济实践呼唤本土理论和数量工具。改革开放以来，…"
