      "content": "以“第二个结合”筑牢文化主体性，创造人类文明新形态来源：解放日报作者：李亚娟2026-09-22 11:16:52“两个结合”尤其是“第二个结合”让中国特色社会主义道路有了更加宏阔深远的历史纵深，拓展了其文化根基，使中国式现代化成为赓续古老文明的现代化，是从中华大地长出来的现代化，是文明更新的结果，而非文明断裂的产物。有了这个结合，我们的文化自信在五千多年文明传承与马克思主义真理力量的双重基石之上，拥有了最坚实的底气时代催生思想，实践孕育理论。党的十八大以来，以习近平同志为核心的党中央围绕建设什么样的中国特色社会主义文化、怎样建设中国特色社会主义文化这一重大时代课题，提出一系列新理念新思想新战略，形成习近平文化思想。《习近平文化文选》第一卷、第二卷（以下简称《文选》）完整呈现了习近平文化思想的形成、丰富、发展过程。认真研读《文选》可以深切体会到，中华民族伟大复兴需要坚定文化自信，坚定文化自…"
