      "content": "锚定新定位，推动中美建设性战略稳定关系行稳致远——写在习近平主席即将对美国进行国事访问之际来源：人民日报作者：国纪平2026-09-22 09:20:27历史长河浩荡奔涌，大国关系的航船，总在时代大潮中不断校准前行航向。应美利坚合众国总统特朗普邀请，习近平主席将于9月23日至25日对美国进行国事访问。两国元首在半年内实现国事互访，具有历史性、里程碑意义。今年5月，习近平主席同特朗普总统在北京举行历史性会晤，共同确立了构建中美建设性战略稳定关系的两国关系新定位，明确两国朝着合作为主、竞争有度、分歧可控、和平可期的方向携手努力，探索新时代大国正确相处之道。穿越风雨，中美关系巨轮锚定全新坐标再启新程。从北京到华盛顿，两国元首时隔4个月再次会晤，将为中美建设性战略稳定关系行稳致远提供战略引领。2026年，注定成为中美关系继往开来的历史性、标志性年份。共同塑造建设性战略稳定的中美关系新图景，这份沉甸…"
