      "content": "求是网评论员：基础研究：如何把握组织化科研和自由探索的关系来源：求是网作者：求是网评论员2026-09-21 08:30:00组织化科研和自由探索，是开展基础研究的主要方式。加强组织化科研，就是要围绕重大战略需求凝练科学问题，集中力量、协同攻关；鼓励自由探索，就是要尊重科研人员的好奇心和探索欲，允许自主选题、大胆试错。两者相辅相成、相互促进。正确认识和处理两者的辩证关系，才能让基础研究既有攻坚的力度，又有探索的活力。在《求是》杂志新近刊发的《在加强基础研究座谈会上的讲话》中，习近平总书记深刻指出，“进入大科学时代，基础研究组织化程度越来越高”。这一重要论断，既是对基础研究发展规律的深刻揭示，也对加强基础研究组织化提出了明确要求。从早期的以自由探索为主，到二战后随着科技不断发展，大团队、大设施、大平台的作用逐步加强，基础研究的组织化程度越来越高。欧洲核子研究中心建造大型强子对撞机，数千名科学…"
