      "content": "汇聚共同发展力量 照亮人类美好未来——全球发展倡议提出5年回眸与展望来源：人民日报作者：寰宇平2026-09-21 09:30:05中国将继续发挥负责任大国作用，持续深化全方位国际发展合作，同世界各国携手同心、砥砺前行，不断推进落实全球发展倡议，完善全球发展治理，共同照亮人类繁荣进步的美好未来发展是人类社会的永恒主题，是破解各类全球性难题的总钥匙。2021年9月21日，习近平主席在第七十六届联合国大会一般性辩论上郑重提出全球发展倡议，为深陷困顿的全球发展事业提供系统性解决方案，贡献兼具温度与力度的中国方案。5年来，中国秉持共促全球发展初心，同各方一道推动全球发展倡议从理念主张转化为落地成果，从中国倡议转化为国际共识，为变乱交织的世界注入了弥足珍贵的发展力量。（一）放眼全球，地缘冲突频发，单边主义抬头，全球经济复苏乏力，发展失衡、治理失效、公平缺失的问题愈发突出。不久前，联合国发布的《202…"
