      "content": "以文明乡风凝聚农业农村现代化精神力量来源：光明日报作者：郝文斌2026-09-21 11:16:002026年6月，习近平总书记在山东省德州市考察时强调，“农业农村现代化关系中国式现代化全局和成色，要以扎实举措做好各项工作，着力提升农业综合生产能力和质量效益，确保粮食等重要农产品稳定供给，因地制宜推进宜居宜业和美乡村建设，引导广大农民群众用勤劳和智慧创造更加美好生活”。文明乡风是推进农业农村现代化的精神内核，是新时代农村精神文明建设的重中之重。新征程上，应以文明乡风建设工程为统领，抓实教育引导、文化滋养、风气整治、组织保障等工作，补齐农村精神文明建设短板，凝聚起广大农民群众共建和美乡村的强大精神力量，为农业农村现代化建设提供坚实思想支撑与道德滋养。抓实教育引导，凝聚乡村振兴思想共识习近平总书记强调：“农村精神文明建设很重要，物质变精神、精神变物质是辩证法的观点，实施乡村振兴战略要物质文明和…"
