      "content": "当科学家海报登上城市大屏来源：人民日报作者：李君强2026-09-21 11:16:01弘扬科学家精神，既要有庄重的纪念，也需要在生活中讲好具体的、鲜活的人和故事逛着商场一抬头，巨幅广告上不是明星代言，也不是新品促销，而是钱学森、邓稼先、袁隆平、于敏等科学家的面孔。近日，这样的画面从山东菏泽、淄博等地开始，陆续出现在内蒙古呼伦贝尔、安徽合肥、浙江杭州等地，路过市民纷纷驻足点赞“打卡”。城市中心的商业大屏，主动把最醒目的位置留给科学家。为什么一张科学家海报，会让那么多人驻足、拍照、转发？我国科技事业取得历史性成就，离不开一代又一代科学家前赴后继、接续奋斗。1958年，34岁的邓稼先接受核武器研制任务，从此隐姓埋名28年，一点点啃下原子弹理论设计的硬骨头；黄旭华被选中参与核潜艇研制，从零起步攻关30年，亲自参加极限深潜试验，展现了“花甲痴翁，志探龙宫，惊涛骇浪，乐在其中”的豪迈气概。一代代科学…"
