      "content": "求是网评论员：基础研究，对建设科技强国意味着什么来源：求是网作者：求是网评论员2026-09-20 14:03:58基础研究是科技创新的源头活水，决定着一个国家科技创新的底蕴和后劲。纵观世界，科技强国无一不是基础研究强国。在《求是》杂志新近刊发的《在加强基础研究座谈会上的讲话》中，习近平总书记鲜明指出：“衡量一个国家的科技实力，一个重要标准就是看基础研究水平。要成为世界科技强国，基础研究必须搞上去。”这一重要论述深刻揭示了加强基础研究对于建设科技强国的先导性、战略性作用。必须锚定科技强国目标，把基础研究摆在战略优先位置，不断以基础研究新成效打牢科技强国建设根基。基础研究是赢得国际科技竞争、掌握发展主动权的关键所在。当前，世界百年变局加速演进，科技竞争日趋激烈，原创性颠覆性创新的重要性日益凸显，基础研究已经成为国际竞争的最前沿和战略制高点。一方面，基础研究与技术研发之间的边界正日益模糊、与产…"
