      "content": "不断提高反腐败穿透力来源：中国纪检监察报作者：记者 李柏逸 李诚贤2026-09-20 09:13:52在二十届中央纪委五次全会上，习近平总书记准确把握反腐败斗争形势任务以及阶段性特征，部署以更高标准、更实举措推进全面从严治党，强调“更加清醒坚定地推进反腐败斗争”。习近平党建思想的科学内涵集中概括为“十四个坚持”，其中之一就是“坚持一体推进不敢腐不能腐不想腐”，深入学习贯彻习近平党建思想，必须深刻认识到，腐败是我们党面临的最大威胁，反腐败是最彻底的自我革命。如何准确把握一体推进“三不腐”的科学方法、有效路径？怎样更加清醒坚定地推进反腐败斗争，不断提高反腐败穿透力？中央纪委国家监委新闻传播中心就此采访了中共中央党史和文献研究院第一研究部副主任王香平、中共中央党校（国家行政学院）科研部副主任洪向华。记者：习近平总书记提出“更加清醒坚定地推进反腐败斗争”这一要求的深刻现实依据是什么？王香平：习近…"
