      "content": "畅通技能人才职业发展通道来源：经济日报2026-09-20 08:42:16第四十八届世界技能大赛将于9月22日至27日在上海举办，全方位展现我国技能发展成就。技能人才是支撑中国制造、中国创造的重要力量。“十五五”规划纲要围绕促进高质量充分就业作出部署，提出大规模开展职业技能培训。今年6月印发的《实施就业优先战略“十五五”规划》提出“畅通技能人才职业发展通道”，7月印发的《人力资源和社会保障事业发展“十五五”规划》强调“加快建设知识型、技能型、创新型劳动者大军，促进技能成才、技能乐业、技能增收”。如何培养造就更多高技能人才？本期特邀专家围绕相关问题进行研讨。支撑中国制造中国创造的重要力量我国技能人才培养取得哪些成果？未来如何畅通其职业发展通道？童天（中国劳动和社会保障科学研究院研究员、中国职业技术教育学会理事）：技能人才是我国人才队伍的重要组成部分，是培育和发展新质生产力、推进中国式现代化…"
