      "content": "以钉钉子精神深化整治群众身边不正之风和腐败问题来源：中国纪检监察报2026-09-19 11:44:34坚决落实习近平总书记、党中央决策部署，中央纪委国家监委连续三年开展群众身边不正之风和腐败问题集中整治。各级纪检监察机关尽锐出战，各地各有关部门合力攻坚，以“宁可掉层皮，也要抓出群众满意的成效”的决心，以超常规举措和力度，从群众最不满意的事情抓起，从危害最大的问题抓起，取得了明显成效。集中整治开展以来，共纠治群众急难愁盼问题652.3万个，覆盖衣食住行、生老病葬、安居乐业等领域。广大人民群众深切感受到“闹心事”少了、“顺心事”多了。集中整治已进入攻坚决战阶段。要清醒看到，群众身边不正之风和腐败问题点多、面广、易发，在基层并未绝迹。要牢记习近平总书记谆谆教诲和殷切嘱托，真正把人民群众放在最高位置，带着对人民群众的深厚感情，以钉钉子精神深化整治群众身边不正之风和腐败问题，一锤接着一锤敲，克难上…"
