      "content": "共享3.0机遇，中国开放红利持续释放来源：人民日报2026-09-19 10:44:47透过一场场盛会，国际社会看到了中国扩大高水平对外开放的坚定步伐，真切感受到了中国新质生产力为全球增长注入的强劲动能9月17日，第二十三届中国—东盟博览会暨中国—东盟商务与投资峰会在广西南宁开幕。榴莲、咖啡、红木等东盟特色产品琳琅满目，参观者络绎不绝；平陆运河专题展区里，来自东盟各国的客商仔细了解这条通江达海的“黄金通道”；“AI大卖场”里，70多家企业带来500多款消费类AI（人工智能）产品，可现场体验、下单……热闹非凡的会场，正是本届东博会“共享3.0机遇，共创美好生活”主题的鲜活注脚。中国机遇的“含金量”，正在转化为中国和东盟双方人民的“获得感”。今年是中国—东盟建立全面战略伙伴关系5周年、中国—东盟建立对话关系35周年。35年来，从建立对话关系到构建更为紧密的中国—东盟命运共同体，双方关系实现跨越…"
