      "content": "以全球治理倡议引领全球海洋治理变革来源：光明日报作者：周江2026-09-18 10:48:05在世界百年未有之大变局加速演进的背景下，全球海洋治理面临一系列突出问题。海洋生态退化、规则体系滞后、发展失衡等相互交织，既有治理共识逐步消解，全球海洋治理赤字日益凸显。在此形势下，迫切需要以全球治理倡议为引领，秉持共商共建共享的全球治理观，推动全球海洋治理变革，促进全球海洋可持续发展。全球海洋治理面临严峻挑战生态系统整体性与治理行动分散性之间的矛盾日益凸显。研究显示，2024年，全球海洋表面平均温度和海洋上层2000米热含量均达到人类有观测记录以来的最高值。海水酸化加速，导致海洋生物多样性持续受损，活体珊瑚覆盖率在过去150年内近乎减半。海洋生态退化造成的全球经济损失每年超过千亿美元，直接影响数亿人口。海洋生态系统的联通性要求全球协同治理，但现实中各国政策协调不足，缺乏有效合作机制。规则体系不健…"
