      "content": "更好满足银发群体高品质需求来源：经济日报作者：李 璐2026-09-18 10:48:03国务院《扩大消费“十五五”规划》部署了未来5年消费重点领域，其中包括扩大银发产品、银发服务消费的目标任务。提振银发消费，既能提升银发群体生活品质，也能从需求侧引导市场加大优质产品和服务供给，通过供需适配推动银发经济高质量发展，进而将人口老龄化挑战转化为扩内需新动能。未来5年，由老年人和备老人群共同组成的银发群体数量大、特定领域需求大、消费潜力大，要将庞大的消费需求有效激活，使其成为释放银发消费潜力的“钥匙”，要找到其中需求最旺、增长最快的核心板块。银发消费有3个特征值得关注：一是银发群体成为自主决策的消费主力。研究发现，根据年龄阶段、健康状况、居住状态等特征划分银发群体，不同群体的消费呈现出较大差异。其中，尤以低龄、健康为特征的“新银发”群体消费意愿强、活力强。近期，国家发展改革委社会发展研究所课题组…"
