      "content": "求是网评论员：以首个五年规划开启香港由治及兴新篇来源：求是网作者：求是网评论员2026-09-17 23:42:342026年9月16日，《香港特别行政区经济和社会发展第一个五年规划（2026—2030年）》正式公布。这是香港回归祖国以来首次编制本地经济和社会发展中长期规划，共7篇28章约6万字，涵盖强化香港四大中心、人才聚集高地、北部都会区、粤港澳大湾区建设，以及民生、公共治理等多个领域，共制定105个指标。这份纲领性文件立足新的历史方位，系统谋划香港经济社会发展长远蓝图，为推动香港由治及兴、实现高质量发展描绘清晰路径、开启新的篇章。过去香港的繁荣，很大程度上依托国际资本进入内地的中介枢纽角色，享受到了巨大的开放红利，但客观上也让香港长期局限于相对单一的功能定位。当前全球产业链供应链加速重构，新一轮科技革命和产业变革深入发展，国际城市之间对资金、技术、人才的争夺日趋激烈。香港要巩固金融、…"
