      "content": "用司法为人工智能系牢“安全带”来源：光明日报作者：方建中2026-09-17 08:43:13近日，最高人民法院正式发布《关于依法审理涉人工智能纠纷案件的意见》（以下简称《意见》），这是我国首部涉人工智能司法裁判规则文件，回应了数字时代人工智能发展的法治关切。我国对人工智能治理的探索由来已久，早在2017年，国务院就印发了《新一代人工智能发展规划》，从国家战略层面提出要建立人工智能法律法规、伦理规范和政策体系。2022年施行的《互联网信息服务算法推荐管理规定》已尝试规范“大数据杀熟”、算法歧视等问题。随后相继颁布的《互联网信息服务深度合成管理规定》《生成式人工智能服务管理暂行办法》则对生成式人工智能的服务规范作出专门规定，重点要求人工智能提供者尊重知识产权、保护个人信息权益。此外，民法典人格权编、个人信息保护法、数据安全法等法律相继实施，也为人工智能治理提供了基础的法律依据。近年来，随着人…"
