      "content": "95后清华核科技博士，当驻村书记，冲动？大材小用？本人回应来源：人民日报微信公众号2026-09-16 18:17:17“镜头低一点，人民高一些！”9月10日，湖北恩施州利川市凉雾乡诸天村村民粟艮树点开微信视频号，就听到一个熟悉的声音。他高兴地把手机举到妻子面前，“你看，咱们的书记又发视频了，还有咱俩的镜头呢！”妻子看着视频里的自己，笑得合不拢嘴，连声赞道“书记真行！”他们说的书记，是今年元月由中国国新控股有限责任公司派出、到诸天村担任第一书记的王帅。把身子沉下去，让头脑跳出来王帅，一个95后的清华工科博士。她出生在山西忻州市代县的一个普通家庭。求学路上，却留下了一串奇迹般的足印：忻州市高考理科第一；清华工科本科+经管双学位；清华核科学与技术博士；北京市优秀毕业生。她的博士导师，是中国工程院院士欧阳晓平。校长拨穗完成学业后，她把自己的作为定在科技与投资的结合部。她要做那个最懂投资的科技人和…"
