      "content": "把农民收入增长作为重大战略性任务来源：经济日报作者：张红宇2026-09-16 10:23:22党的十八大以来，我国“三农”发展取得历史性成就、发生历史性变革。乡村振兴战略全面实施，农业强国建设迈出坚实步伐，农业综合生产能力稳步增强，宜居宜业和美乡村建设扎实推进，农业农村现代化水平加速提升，绝对贫困问题得到历史性解决，成就举世瞩目。习近平总书记强调：“各级党委和政府要坚持把解决好‘三农’问题作为重中之重，坚持五级书记抓乡村振兴，奋发进取、真抓实干，努力把农业建成现代化大产业、使农村基本具备现代生活条件、让农民生活更加富裕美好。”农业农村现代化关系中国式现代化全局和成色，当前面临的一个重要挑战就是农民收入整体上长期偏低，城乡居民收入差距缩小进程相对缓慢。“十五五”时期，必须把促进农民稳定增收摆在“三农”工作的重要位置，千方百计提高农民收入，加快缩小城乡收入差距，为扎实推进乡村全面振兴、全面建…"
