      "content": "善用“大思政课”，创新激活文化育人新动能来源：光明日报作者：叶阁泽2026-09-14 14:24:10文以载道，道以育人。文化是一个国家、一个民族的灵魂，也是涵养时代新人不可或缺、不可替代的深厚土壤。充分激活文化的育人功能，需要一种大格局、大视野、大贯通的教育创新作为支撑。“大思政课”正是这样一种战略性、系统性、实践性的教育创举，它以协同育人的格局汇聚力量，以连接古今的视野赓续文脉，以知行合一的贯通承载厚重，使文化育人工作更加系统、更加深刻、更加富有成效。如何以“大思政课”的集成创新激活文化育人新动能，是时代交给我们的一道必答题。文化育人的本质在于以文化人，根基在文化，关键在转化，让文化从外在于人的知识转化为内在于人的价值准则。“大思政课”植根于中华民族灿烂文化，立足于铸魂育人的教育本源，其深层追求正是让优秀文化进入青年人的精神世界，内化为他们日用而不觉的行为准则。实现这一追求，必须紧紧…"
