      "content": "求是网评论员：以“大金砖合作”更好引领全球南方发展来源：求是网作者：求是网评论员2026-09-13 20:45:252026年9月12日，习近平主席在印度新德里出席金砖国家领导人第十八次会晤第一阶段会议并发表重要讲话，全面回顾金砖合作机制自立自强、风雨同舟、成果丰硕的发展历程，立足全球南方群体性崛起的时代背景，为推动“大金砖合作”高质量发展，引领国际秩序朝着更加公正合理的方向发展提供重要遵循。今年适逢金砖国家合作20周年。金砖合作机制从最初的“金砖四国”发展到如今拥有11个正式成员国和10个伙伴国的“金砖大家庭”，总人口占全球近一半，经济总量约占世界30%，贸易总额占全球五分之一，整体实力不断提升，发展潜力日益增长，成为当今世界最重要的新兴市场和发展中国家团结合作平台。20年来，金砖国家坚持独立自主，积极探索符合自身国情的发展道路，携手应对国际金融危机、新冠疫情、气候变化等挑战，实现历史…"
