      "content": "为依法推普注入强大文化力量来源：光明日报作者：周作明 侯晓琳2026-09-13 12:27:26编者按2026年1月1日起，新修订的《中华人民共和国国家通用语言文字法》正式实施，标志着国家通用语言文字推广普及工作迈入更加注重法治引领、协同发力、提质增效的新阶段。今年，第29届国家通用语言文字推广普及宣传周（简称“第29届推普周”）将于9月14日至20日在全国开展多项活动。本刊今天特推出专版，聚焦今年的推普周主题“依法推广普及国家通用语言文字，奋进强国建设新征程”。随着新修订的《中华人民共和国国家通用语言文字法》全面实施，我国国家通用语言文字推广普及迈入法治化高质量发展新阶段。语言文字兼具交际媒介、文明载体、价值塑造三重功能，高质量推普不仅是语言知识传授和语言技能训练，更是赓续中华文脉、凝聚民族共识、塑造共同价值的文化实践。国家通用语言文字法将“铸牢中华民族共同体意识，坚定文化自信”写入立…"
