      "content": "中国共产党领导红军长征的光辉历程和伟大意义来源：光明日报作者：杨凤城2026-09-12 09:57:04今年是中国工农红军长征胜利90周年。习近平总书记指出，长征是一次理想信念的伟大远征，一次检验真理的伟大远征，一次唤醒民众的伟大远征，一次开创新局的伟大远征。今天回顾长征历史，体悟长征精神，缅怀先烈事迹，对赓续红色血脉，传承红色基因，走好新时代的长征路有重要意义。艰苦卓绝的战略大转移红军长征不是一次主动的战略进军，而是中国革命在极端危急形势下的艰难突围。1933年9月，蒋介石调集百万重兵，对中央革命根据地发动规模空前的第五次“围剿”。1934年5月，中央书记处会议决定，将红军主力撤离中央根据地，实行战略转移。10月，中央红军主力8.6万余人，从江西瑞金、于都和福建长汀、宁化等地集结出发，进行战略大转移。浴血湘江，通道转兵。长征初期，国民党调集各路大军层层布防，红军将士连续突破敌人四道封锁…"
