      "content": "筑牢数字文化遗产的网络安全防线来源：光明日报作者：柴荣2026-09-12 11:18:44随着数字技术快速发展，科技赋能文化遗产保护越发普遍。文化遗产的数字化转型在拓展保护与传播路径的同时，也存在一定网络安全风险。当前，大数据、三维重建、数字孪生等技术已广泛用于文物记录、修复、展示与管理中，文化遗产数字记录涉及采集、存储、传输、利用各环节，其真实性、完整性和可访问性高度依赖网络环境与数据管理制度。然而，数据泄露、内容篡改、跨境窃取、算法滥用等网络安全威胁同步存在。如何在数字化进程中系统识别并有效防控网络安全风险，已成为文化遗产保护法治建设亟须回应的问题。重视网络安全风险挑战数字文化遗产以数据形态存在，其权属、利用、传承等问题与传统文化遗产有很大差异。数字化不仅为文化遗产提供了“第二生命”，既以数字形态永久保存文化遗产信息，也为公众接触理解文化遗产开辟了全新路径。2025年，浙江省杭州市“…"
