      "content": "求是网评论员：中国始终是世界经济发展的积极贡献者和机遇提供者来源：求是网作者：求是网评论员2026-09-11 08:33:06近期，美国外交关系委员会主席迈克尔·弗罗曼在美国《外交事务》刊文，再度炒作所谓“中国产能过剩”的论调，将中国的贸易顺差解释为向世界转嫁国内失衡，并假定全球市场吸纳能力已接近极限，声称一旦中国出口受阻，就可能引发一系列经济社会问题并波及全球，成为下一场全球经济危机的源头。这一叙事看似环环相扣，实则颠倒是非，根本站不住脚，不过是为鼓噪美国出台歧视性贸易限制措施而进行的又一次话语操弄而已。首先来看所谓“产能过剩”的说法。弗罗曼根据中国工业生产规模较大、一些企业亏损和制造业出口增长等现象而得出中国产能过剩的结论，并将其归因于政府补贴等产业政策。但是判断产能是否过剩，不能只看生产规模和出口数量，应当结合供需关系和产能利用状况进行综合衡量。从产能利用看，2025年中国规模以上…"
