      "content": "开创“大金砖合作”高质量发展新局面来源：人民日报2026-09-11 09:05:45中方愿同金砖各国一道，淬炼金砖成色，展现金砖力量，不断开创“大金砖合作”高质量发展新局面，携手更多全球南方国家共同推动构建人类命运共同体应印度共和国总理莫迪邀请，习近平主席将于9月12日至13日赴印度新德里出席金砖国家领导人第十八次会晤。金砖合作机制已成为当今世界最重要的新兴市场国家和发展中国家团结合作平台。中国作为这一机制的坚定支持者和参与者，国际社会高度期待推动“大金砖合作”高质量发展的中国主张。一个基础更牢、动能更足、影响更大的“大金砖”，将为维护世界和平、促进共同发展、完善全球治理发挥更大作用。此次峰会恰逢金砖合作机制成立20周年。20年来，金砖合作机制从最初的新兴市场对话平台，到横跨四大洲、涵盖政治安全、经贸财金、人文交流等领域的重要多边机制，金砖大家庭不断壮大，合作的道路越走越宽，日益成为世界…"
