      "content": "具身智能不应重展示轻应用来源：经济日报作者：刘成志2026-09-11 10:10:05一段时间以来，具身智能持续受到关注。前段时间，工业和信息化部、国务院国资委启动人形机器人与具身智能实景实训专项行动，提出推动重点产品开启“作业模式”，在代表性场景开展应用验证和常态化部署。从产业实践到政策部署，具身智能正加快从技术展示走向实际作业。具身智能受到重视，是因为人工智能开始更多参与现实生产活动。过去，人工智能主要用于信息处理、内容生成和辅助决策。如今，机器人和各类智能装备把这些能力带进了生产现场，可以承担搬运、装配、巡检、维护等具体任务。对企业来说，机器人能不能完成几个高难度动作并不是最重要的，关键是能长期稳定工作，提高效率、降低成本，减少人员进入危险和高强度岗位。推动具身智能进入“作业模式”，是其从技术创新迈向现实生产力的关键一步。近两年，我国具身智能产业化步伐明显加快。产业竞争正由单一整机…"
