      "content": "学习在理丨大力弘扬科学家精神2026年09月11日09:00来源：人民网-中国共产党新闻网222订阅取消订阅已收藏收藏大字号点击播报本文，约科学成就离不开精神支撑。科学家精神是科技工作者在长期科学实践中积累的宝贵精神财富。党的十八大以来，习近平总书记多次强调要大力弘扬科学家精神，极大鼓舞和激励了广大科学家和科技工作者不断攀登科学高峰。今年9月是第二个“全国科普月”。让我们继续传承好科学家精神，接续奋斗、勇毅前行，朝着建成科技强国的宏伟目标奋勇前进。文案、制作：黄瑾资料来源：人民日报、央视新闻、央广网等(责编：黄瑾、秦华)学习路上时习之习近平系列重要讲话数据库中央文件学习宣传贯彻党的二十大精神跟着总书记学党史数据库中央和国家机关建设模范机关言之有理学习文选微信“扫一扫”添加“学习大国”分享到：推荐阅读打开客户端体验更多服务打开"
