      "content": "用教育家精神铸魂强师来源：吉林日报作者：陈雪梅2026-09-10 09:47:57教师是立教之本、兴教之源。教师队伍建设是推动教育、科技、人才一体发展的关键所在。教育家精神凝练了我国千百年来尊师重教的优良传统，汇聚了教育事业发展的价值追求，为广大教师修身立德、教书育人、履职尽责提供了根本遵循。立足新时代，面对教育改革发展的新形势、人才培养的新任务、社会发展的新需求，唯有大力弘扬教育家精神，引导广大教师坚守教育初心、深耕育人实践、锤炼过硬本领、勇担时代使命，才能锻造出担当民族复兴重任、赋能国家高质量发展的大国良师队伍，为教育强国、人才强国建设注入源源不断的动力。以报国担当为使命，扛起大国良师应有责任。教育事关民族未来、国运兴衰，教师的三尺讲台连接的是万家灯火、国家未来。心有大我、至诚报国，将个人教育理想融入国家发展大局，是教育家精神最鲜明、最深刻的特质。长期以来，无数教育工作者默默奉献、躬…"
