      "content": "加强新时代历史文化遗产保护传承来源：经济日报作者：孙代尧2026-09-09 14:20:29西周礼器“何尊”铭文里的“宅兹中国”、上海博物馆“何以中国”系列展览等，均折射出中华文明起源、形成与发展的宏大命题。保护好、弘扬好、发展好中华文明瑰宝，让历史文化遗产焕发新活力、绽放新魅力，是增强文化自信、建设社会主义文化强国的应有之义，也是筑牢中国式现代化的文化根基、实现中华民族伟大复兴的必然要求。中国共产党是中华优秀传统文化的忠实继承者和弘扬者，历来坚持马克思主义历史观和方法论，秉持古为今用的原则传承中华民族优秀历史文化遗产。党的十八大以来，习近平总书记站在强国建设、民族复兴的战略高度，以宏阔视野和格局提出一系列关于历史文化遗产保护的新观点、新论述，成为习近平文化思想中具有鲜明特色的重要组成部分，为加强新时代文化遗产保护传承提供了科学指引。充分认识历史文化遗产独特价值文化遗产镌刻着国家的历史文…"
