      "content": "多措并举，推动商品消费稳中提质来源：光明日报作者：李峄2026-09-09 14:20:30“十五五”期间，我国消费市场发展将进入扩量提质的关键时期，商品消费作为消费市场的基本盘，将在促消费、惠民生中发挥重要作用。近日，商务部等7部门发布《关于推动商品消费扩容升级的实施意见》。作为“十五五”开局之年扩大商品消费的重要举措，该文件聚焦多个领域商品消费，通过供给侧和流通侧共同发力，推动商品消费稳中提质，为扩大内需、建设强大国内市场提供有力支撑。当前，我国商品消费进入稳量增长阶段。2025年，我国社会消费品零售总额首次突破50万亿元，同比增长3.7%，最终消费对经济增长的贡献率达52%，持续发挥经济发展主引擎作用。此次文件提出到2030年，社零总额达60万亿元左右的目标，培育形成绿色消费、智能消费、健康消费等10万亿级市场，推动超大规模市场优势持续显现。如何进一步激活商品消费增长新动能，可探索从…"
