      "content": "启智润心 弘扬教育家精神当好学生引路人来源：人民日报作者：记者 丁雅诵 门杰伟2026-09-09 14:20:33“要弘扬教育家精神，加强师德师风建设，培养造就高素质专业化教师队伍。”——2026年7月，习近平总书记对基础教育工作作出重要指示强调吉林大学朝阳校区，黄大年纪念馆新馆前段时间落成。展厅里，黄大年“人民教育家”荣誉证书与奖章静静陈列，旁边是他手写的日程表，每一天都排得密密麻麻。2017年，习近平总书记对黄大年同志先进事迹作出重要指示，强调“把爱国之情、报国之志融入祖国改革发展的伟大事业之中、融入人民创造历史的伟大奋斗之中”。殷切期望，落地生根。同年，教育部启动全国高校黄大年式教师团队创建活动，首批认定的201个教师团队来自200所高校，覆盖各学科门类和东中西部省份。2021年，习近平总书记回信勉励全国高校黄大年式教师团队代表，“立德修身，潜心治学，开拓创新，真正把为学、为事、为…"
