      "content": "与古为新，是非遗走红的密码来源：光明日报作者：任赖锬2026-09-08 13:43:52近日，亮相世界技能博物馆的德化白瓷作品《神话》火爆全网。该作品以影视人物“玉漱公主”为原型，器型精巧，“远看是纱，近看是瓷”，0.2毫米的瓷纱轻盈通透，0.3毫米的瓷发丝纤毫毕现，极致细腻的工艺惊艳无数网友。这件作品诞生的背后，其实是孩子的一次挑战。非遗传承人连德理与妻子曾碧珍跳出沿袭数十年的传统创作框架，从零调试瓷土配方、反复打磨烧制工艺，历经上百次试验突破薄胎白瓷的工艺极限，最终打造出这件兼具古法韵味与当代审美的作品，也让千年德化白瓷打破了刻板印象，走进了更多年轻人的视野。事实上，这种“技艺精湛、受众小众”的困境，并非德化白瓷独有，而是当下众多传统非遗传承的共性问题。不少非遗从业者将坚守古法简单等同于因循守旧，固守传统技法与题材，忽视了新时代大众尤其是年轻群体的审美变迁，硬生生割裂了非遗与当代生活…"
