      "content": "伟大长征精神启迪年轻一代重担当来源：光明日报作者：范晶2026-09-07 10:31:50在红军长征胜利90周年之际，江西省瑞金市博物馆推出的“红军不怕远征难——中央红军长征决策和出发历史展览”以“红军不怕远征难”为主题，展出300余幅历史图片、30件珍贵文物复制件及翔实文献史料，全景式呈现中央红军从战略决策到胜利会师的壮阔历程。伟大长征精神是中国共产党人精神谱系中熠熠生辉的篇章，是中华民族宝贵的精神财富。习近平总书记深刻指出：“每一代人有每一代人的长征路，每一代人都要走好自己的长征路。”回望90年前那场人类历史上的伟大奇迹，红军将士用理想信念、热血生命铸就了伟大长征精神。其中“为了救国救民，不怕任何艰难险阻，不惜付出一切牺牲”的深刻内涵，穿越时空、历久弥新，为新时代青年标定了“为何奋斗、如何奋斗、为谁奋斗”的价值坐标。将伟大长征精神与青年成长相结合，重在汲取信仰之力、奋进之力、奉献之力…"
