      "content": "在守正创新中把老字号传承发展好来源：人民日报作者：祝合良2026-09-07 10:31:47老字号是我国工商业长期发展过程中形成的民族品牌，蕴含着巨大的经济价值、社会价值、文化价值。今年年初，习近平总书记在北京考察时指出：“现在一些老字号传承发展也面临挑战，怎么激发活力？这并不是简单地改头换面，要保留住真正的内涵，同时提升各方面的服务。”“十五五”规划纲要提出“推动老字号、国货潮牌做精做强”。这为我们在守正创新中把老字号传承发展好指明了方向、提供了遵循。老字号具有历史底蕴深厚、文化特色鲜明、工艺技术独特、设计制造精良、产品服务优质、营销渠道高效、社会广泛认同等鲜明特点。近年来，在一系列政策推动下，我国老字号发展活力不断增强。根据《中华老字号年度发展报告（2025）》，全国1450个中华老字号企业总体发展良好，品牌平均存续时间超过145年，百年老店占比超过六成，拥有各类非遗1200多项。与…"
