      "content": "求是网评论员：管党治党会影响经济社会发展吗？来源：求是网作者：求是网评论员2026-09-06 09:23:40随着全面从严治党深入推进，广大党员、干部落实管党治党政治责任的意识不断增强，能力不断提高，但也有一些错误认识需要厘清。比如，有人认为，“全面从严治党管得太紧，抓吃喝过了头，反腐败用力过猛，影响经济社会发展”；有人认为，“管党治党抓得太严，束缚了党员、干部的手脚，影响了干事创业积极性”；等等。产生这些错误认识，究其根源，就在于对管党治党与经济社会发展关系的认识有偏差。只有正确认识和把握两者的辩证关系，落实好管党治党政治责任，才能为经济社会发展提供坚强保障。习近平总书记强调：“管党治党越有效，经济社会发展的保障就越有力。”这一重要论述，深刻揭示了管党治党与经济社会发展的内在逻辑。我们党在有着14亿多人口的大国长期执政，管党治党与经济社会发展不是“两张皮”，更不是此消彼长的对立关系，而…"
