      "content": "让真善美种子在孩子们心中生根发芽——习近平总书记的贺信激励少儿工作者担当使命奋发有为来源：人民日报作者：记者 刘 阳2026-09-06 15:11:14在中央广播电视总台《小喇叭》节目开播70周年之际，习近平总书记发来贺信表示祝贺，勉励大家“落实立德树人根本任务，紧扣时代发展脉搏，深耕少儿文化沃土，用心用情创作更多传播真善美、受到孩子们喜爱的优秀作品，为培养德智体美劳全面发展的社会主义建设者和接班人作出更大贡献”。习近平总书记的贺信让《小喇叭》节目组和广大少儿工作者倍感振奋、备受鼓舞。大家表示，要全力做好少儿德育美育工作，创作出更多少儿文艺精品，凝聚全社会共识和力量，助力少年儿童向上向善、成长成才。落实立德树人根本任务习近平总书记的贺信充分体现了党中央对亿万少年儿童的亲切关怀、对少儿文艺工作的高度重视。《小喇叭》于1956年9月4日开播，是新中国首个专为学龄前儿童打造的广播节目，目前已成…"
