      "content": "更好推动人工智能赋能健康产业来源：经济日报作者：刘 萱2026-09-04 17:32:43人民健康是社会主义现代化的重要标志，也是广大人民群众的共同追求。“十五五”规划纲要提出“有序推动数智技术在辅助诊疗、精准医疗、健康管理、医保服务、养老助残等场景的应用”，为推进全民健康数智化建设提供助力。当前新技术、新业态、新场景不断涌现，深化人工智能与健康产业融合发展，既是优化医疗资源配置、完善全生命周期健康服务的现实需要，也是加快健康中国建设、以人口高质量发展支撑中国式现代化的应有之义。健康产业兼具公益性与市场化双重属性，涵盖预防、诊疗、康复、医药研发、健康管理全链条，服务覆盖全人群、全生命周期，具备专业性强、民生关联度高、服务连续性突出等特点。健康产业发展既要坚持公平普惠，提供基础医疗服务；也要激发市场活力，满足群众个性化、高品质、多样化健康需求。当前，我国健康产业发展还存在优质资源布局不均、…"
