      "content": "把谋事和干事有机统一起来来源：人民日报作者：郁钟华2026-09-03 12:32:01为人民出政绩、以实干出政绩，始终离不开谋事与干事。谋事，是科学决策，定方向、定思路；干事，是实干苦干，抓落实、求实效。把谋事和干事有机统一起来，政绩才立得住、过得硬。习近平总书记深刻指出：“正确政绩观要求我们坚持从实际出发、按规律办事，通过科学决策和实干苦干，创造经得起实践和历史检验、真正造福人民、得到群众公认的业绩。”当前，“十五五”开局之年已行过半程，树立和践行正确政绩观学习教育已基本结束。应当认识到，这次学习教育不是终点而是新的起点。树立和践行正确政绩观是一项长期任务，必须久久为功。学得深不深、查得准不准、改得到不到位，最终要看能否巩固拓展学习教育成果，将其转化为谋事的章法与干事的实效。现实中，一些党员干部不缺干事的热情，缺的是谋事的能力：习惯于用“过去怎么干”推导“现在怎么干”，用“别的地方怎么…"
