      "content": "持续推动高水平科技自立自强取得新突破来源：光明日报作者：陈伟伟2026-09-03 12:32:02近日，国新办举行“开局起步‘十五五’”系列主题新闻发布会，工信部相关负责人在答记者问时强调，要着力加强产业创新，加强原始创新和关键核心技术攻关，提升制造业创新体系整体效能，不断催生新质生产力。从世界机器人大会上众多应用场景亮相，展现产业“智”变升级，到机器人、人工智能、创新药扬帆出海，成为引领我国产业跃升的增长引擎……这些都启示我们，推进高水平科技自立自强，应坚持系统观念，统筹推进技术攻坚、供需贯通与生态构建，引导创新从局部突破向体系化进阶。科技自立自强，前提在自立。党的十八大以来，以习近平同志为核心的党中央坚持把科技创新摆在国家发展全局的核心位置，我国科技事业实现了历史性、整体性、格局性重大变化。据统计，2025年我国全社会研究与试验发展（R&D）经费投入达到约3.9万亿元，投入强度首次超…"
