      "content": "2025年人权保障立法工作述评来源：人权研究微信公众号作者：王媛媛2026-09-02 11:19:55党的十八大以来，以习近平同志为核心的党中央高度重视尊重和保障人权，把人权保障纳入全面依法治国战略布局，不断提升人权法治化保障水平，推动我国人权事业取得历史性成就，为世界人权事业发展作出了重大贡献。坚持以人民为中心作为习近平法治思想的核心要义，深刻回答了法治建设为了谁、依靠谁的根本问题。习近平总书记强调，“推进全面依法治国，根本目的是依法保障人民权益”，“法治是人权最有效的保障”。习近平总书记关于加强人权法治保障的重要论述科学揭示了法治与人权的内在统一，为新时代人权法治保障事业指明了前进方向、提供了根本遵循。立法是实行法治的前提和基础。2025年，全国人大及其常委会紧扣党和国家工作大局，在人权保障立法方面交出了一份沉甸甸的答卷。这一年，全国人大常委会法制工作委员会（以下简称全国人大常委会法…"
