      "content": "求是网评论员：平台经济发展既要有效率更要有温度来源：求是网作者：求是网评论员2026-08-25 08:14:52近日，北京推动美团、淘宝闪购、京东外卖试行“红灯停表”，骑手等红灯的时间将在配送考核中相应顺延，并针对恶劣天气、复杂路况、转单等情况增加配送时长。等红灯，配送计时也暂时停下来，这几十秒时间的调整，体现的是对外卖骑手权益的更多考量。平台企业科学合理设置配送时间，有助于减少不必要的赶时间、抢速度，更好保障骑手配送安全。透过“红灯停表”，人们看到的不只是外卖骑手的配送时间宽松了一些，更是在多方协商推动平台经济规范健康发展中平台企业自律意识的增强。如今，平台经济已深度融入生产生活，平台企业连接着广大劳动者、商家和消费者，平台规则涉及多方切身利益。订单怎么分、时间怎么算、报酬怎么定，平台往往通过算法将这些用工规则具体落实。算法如何设计和运用，不仅关系平台运行效率，也直接影响劳动者的劳动条…"
